INSERT INTO blocks (block_id, turn_uuid, turn_no, seq, role, kind, chars, tool_name, tool_use_id, is_error, redacted, signature_sha256, signature_len, privacy_zone, zone_reason, zone_match, text) VALUES (20, 'e9e0c9ae-f2f4-49cb-946b-5c04346682e0', 15, 2, 'assistant', 'tool_use', 42670, 'Write', 'toolu_01Qay2JD4HEXAikRVGxZ4y3z', 0, 0, NULL, NULL, 'Confidential', 'medical', 'pots', '{"content": "<title>Field Test #1 — How I Work With AI</title>\n<style>\n  :root {\n    --ground:#EFF2F3; --surface:#FFFFFF; --surface-2:#E5EAEC; --line:#C9D4D8;\n    --ink:#131E26; --ink-2:#465A66; --ink-3:#71868F;\n    --accent:#0D6E68; --accent-soft:#D6EAE8; --accent-line:#8FC7C2;\n    --stable:#2E7D53; --monitor:#8E6A10; --warn:#B0511C; --crit:#96272 7;\n    --crit:#962727;\n    --shadow:0 1px 2px rgba(19,30,38,.06), 0 8px 24px -16px rgba(19,30,38,.28);\n    --serif: \"Iowan Old Style\",\"Palatino Linotype\",Palatino,\"Book Antiqua\",Georgia,serif;\n    --sans: system-ui,-apple-system,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n    --mono: ui-monospace,SFMono-Regular,\"SF Mono\",Menlo,Consolas,\"Liberation Mono\",monospace;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --ground:#0C1418; --surface:#121D23; --surface-2:#1A2932; --line:#26383F;\n      --ink:#E3EDF0; --ink-2:#9DB2BC; --ink-3:#7A929D;\n      --accent:#4FBFB4; --accent-soft:#12332F; --accent-line:#2C5F5A;\n      --stable:#5FB483; --monitor:#CBA13C; --warn:#DD8850; --crit:#D96A6A;\n      --shadow:0 1px 2px rgba(0,0,0,.4), 0 8px 24px -16px rgba(0,0,0,.7);\n    }\n  }\n  :root[data-theme=\"dark\"] {\n    --ground:#0C1418; --surface:#121D23; --surface-2:#1A2932; --line:#26383F;\n    --ink:#E3EDF0; --ink-2:#9DB2BC; --ink-3:#7A929D;\n    --accent:#4FBFB4; --accent-soft:#12332F; --accent-line:#2C5F5A;\n    --stable:#5FB483; --monitor:#CBA13C; --warn:#DD8850; --crit:#D96A6A;\n    --shadow:0 1px 2px rgba(0,0,0,.4), 0 8px 24px -16px rgba(0,0,0,.7);\n  }\n  :root[data-theme=\"light\"] {\n    --ground:#EFF2F3; --surface:#FFFFFF; --surface-2:#E5EAEC; --line:#C9D4D8;\n    --ink:#131E26; --ink-2:#465A66; --ink-3:#71868F;\n    --accent:#0D6E68; --accent-soft:#D6EAE8; --accent-line:#8FC7C2;\n    --stable:#2E7D53; --monitor:#8E6A10; --warn:#B0511C; --crit:#962727;\n    --shadow:0 1px 2px rgba(19,30,38,.06), 0 8px 24px -16px rgba(19,30,38,.28);\n  }\n\n  * { box-sizing: border-box; }\n  body {\n    margin:0; background:var(--ground); color:var(--ink);\n    font-family:var(--sans); font-size:16px; line-height:1.55;\n    -webkit-font-smoothing:antialiased;\n  }\n  .wrap { max-width:940px; margin:0 auto; padding:0 20px 80px; }\n  section { padding-top:52px; }\n  h1,h2,h3 { text-wrap:balance; margin:0; }\n  p { margin:0; }\n\n  /* ---------- utility type ---------- */\n  .eyebrow {\n    font-family:var(--mono); font-size:11px; letter-spacing:.13em;\n    text-transform:uppercase; color:var(--ink-3);\n  }\n  .id {\n    font-family:var(--mono); font-size:12px; letter-spacing:.02em;\n    color:var(--accent); font-weight:600;\n  }\n  .lede { font-size:16px; color:var(--ink-2); max-width:62ch; }\n\n  /* ---------- masthead ---------- */\n  header.mast { padding:56px 0 0; }\n  .mast h1 {\n    font-family:var(--serif); font-weight:600; letter-spacing:-.015em;\n    font-size:clamp(30px,5.2vw,46px); line-height:1.08; margin:14px 0 12px;\n    max-width:20ch;\n  }\n  .verdictbar {\n    display:flex; flex-wrap:wrap; align-items:center; gap:10px; margin-top:22px;\n  }\n  .verdict {\n    display:inline-flex; align-items:baseline; gap:8px;\n    font-family:var(--mono); font-size:12px; letter-spacing:.08em; text-transform:uppercase;\n    background:var(--accent-soft); color:var(--accent);\n    border:1px solid var(--accent-line); border-radius:2px; padding:6px 11px; font-weight:600;\n  }\n  .verdict b { font-size:12px; }\n\n  .stats {\n    display:grid; grid-template-columns:repeat(auto-fit,minmax(104px,1fr));\n    gap:1px; background:var(--line); border:1px solid var(--line);\n    margin-top:24px; border-radius:3px; overflow:hidden;\n  }\n  .stat { background:var(--surface); padding:13px 14px; }\n  .stat .n {\n    font-family:var(--mono); font-size:23px; font-weight:600; letter-spacing:-.02em;\n    font-variant-numeric:tabular-nums; display:block; line-height:1.1;\n  }\n  .stat .k {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--ink-3); margin-top:5px; display:block;\n  }\n  .stat.short .n { color:var(--warn); }\n\n  /* ---------- section heads ---------- */\n  .shead { border-top:1px solid var(--line); padding-top:16px; margin-bottom:22px; }\n  .shead h2 {\n    font-family:var(--serif); font-weight:600; font-size:clamp(21px,3vw,27px);\n    letter-spacing:-.01em; margin:8px 0 8px; line-height:1.2;\n  }\n\n  /* ---------- the loop diagram ---------- */\n  .loop {\n    background:var(--surface); border:1px solid var(--line); border-radius:4px;\n    padding:26px 22px 20px; box-shadow:var(--shadow); overflow-x:auto;\n  }\n  .track { display:flex; align-items:stretch; gap:0; min-width:640px; }\n  .node {\n    flex:1; background:var(--surface-2); border:1px solid var(--line); border-radius:3px;\n    padding:12px 13px; display:flex; flex-direction:column; gap:5px;\n  }\n  .node .t { font-weight:600; font-size:13.5px; line-height:1.3; }\n  .node .s { font-family:var(--mono); font-size:11px; color:var(--ink-3); }\n  .node.flag { border-color:var(--warn); background:var(--surface); box-shadow:inset 3px 0 0 var(--warn); }\n  .node.flag .s { color:var(--warn); }\n  .arrow {\n    flex:0 0 34px; display:flex; align-items:center; justify-content:center;\n    color:var(--ink-3); font-size:15px;\n  }\n  .returnrail { min-width:640px; margin-top:12px; display:flex; align-items:center; gap:10px; }\n  .returnrail .bar {\n    flex:1; height:26px; border:1px dashed var(--crit); border-top:none;\n    border-radius:0 0 4px 4px;\n  }\n  .returnlab {\n    font-family:var(--mono); font-size:11px; color:var(--crit); white-space:nowrap;\n    letter-spacing:.02em;\n  }\n  .loopcap { font-size:13.5px; color:var(--ink-2); margin-top:16px; max-width:66ch; }\n\n  /* ---------- pattern cards ---------- */\n  .patterns { display:grid; gap:10px; }\n  .pcard {\n    width:100%; text-align:left; font:inherit; color:inherit; cursor:pointer;\n    background:var(--surface); border:1px solid var(--line); border-left:3px solid var(--accent-line);\n    border-radius:3px; padding:15px 17px; display:grid; gap:7px;\n    transition:border-color .14s ease, background .14s ease;\n  }\n  .pcard:hover { border-left-color:var(--accent); background:var(--surface); }\n  .pcard[aria-pressed=\"true\"] { border-left-color:var(--accent); background:var(--accent-soft); }\n  .pcard:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }\n  .prow { display:flex; align-items:baseline; gap:10px; flex-wrap:wrap; }\n  .pcard .claim { font-weight:600; font-size:15.5px; letter-spacing:-.005em; }\n  .pcard .stall { font-size:13.5px; color:var(--ink-2); }\n  .pcard .stall b { font-weight:600; color:var(--ink); }\n  .chips { display:flex; gap:5px; flex-wrap:wrap; margin-left:auto; }\n  .chip {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.04em;\n    border:1px solid var(--line); border-radius:2px; padding:2px 6px; color:var(--ink-3);\n    background:var(--ground);\n  }\n\n  /* ---------- fixes table ---------- */\n  .tablewrap { overflow-x:auto; border:1px solid var(--line); border-radius:3px; background:var(--surface); }\n  table { border-collapse:collapse; width:100%; min-width:600px; font-size:14px; }\n  th, td { text-align:left; padding:11px 14px; border-bottom:1px solid var(--line); vertical-align:top; }\n  th {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--ink-3); font-weight:600; background:var(--surface-2);\n  }\n  tbody tr:last-child td { border-bottom:none; }\n  td.sev { font-family:var(--mono); font-size:11px; letter-spacing:.05em; white-space:nowrap; }\n  .dot { display:inline-block; width:7px; height:7px; border-radius:50%; margin-right:7px; vertical-align:1px; }\n  .s-high .dot { background:var(--crit); } .s-high { color:var(--crit); }\n  .s-med .dot  { background:var(--warn); } .s-med  { color:var(--warn); }\n  .s-low .dot  { background:var(--ink-3); } .s-low { color:var(--ink-3); }\n  tr.act td:first-child { box-shadow:inset 3px 0 0 var(--accent); }\n  .now {\n    font-family:var(--mono); font-size:10px; letter-spacing:.08em; text-transform:uppercase;\n    color:var(--accent); border:1px solid var(--accent-line); border-radius:2px;\n    padding:1px 5px; margin-left:8px; white-space:nowrap;\n  }\n\n  /* ---------- evidence ---------- */\n  .filters { display:flex; flex-wrap:wrap; gap:6px; align-items:center; margin-bottom:14px; }\n  .fgroup { display:flex; gap:4px; align-items:center; }\n  .flabel {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--ink-3); margin-right:3px;\n  }\n  .f {\n    font-family:var(--mono); font-size:11.5px; cursor:pointer; color:var(--ink-2);\n    background:var(--surface); border:1px solid var(--line); border-radius:2px; padding:4px 9px;\n    transition:all .12s ease;\n  }\n  .f:hover { border-color:var(--accent-line); color:var(--ink); }\n  .f[aria-pressed=\"true\"] { background:var(--accent); border-color:var(--accent); color:var(--surface); }\n  :root[data-theme=\"dark\"] .f[aria-pressed=\"true\"], .f[aria-pressed=\"true\"] { color:#fff; }\n  @media (prefers-color-scheme: dark) { .f[aria-pressed=\"true\"] { color:#08110F; } }\n  :root[data-theme=\"dark\"] .f[aria-pressed=\"true\"] { color:#08110F; }\n  :root[data-theme=\"light\"] .f[aria-pressed=\"true\"] { color:#fff; }\n  .f:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }\n  .fstate {\n    font-family:var(--mono); font-size:11.5px; color:var(--ink-3); margin-left:auto;\n    font-variant-numeric:tabular-nums;\n  }\n\n  .notes { display:grid; gap:7px; }\n  details.note {\n    background:var(--surface); border:1px solid var(--line); border-radius:3px;\n  }\n  details.note[open] { border-color:var(--accent-line); }\n  details.note.lit { box-shadow:inset 3px 0 0 var(--accent); }\n  summary { cursor:pointer; padding:12px 15px; display:flex; gap:11px; align-items:baseline; list-style:none; }\n  summary::-webkit-details-marker { display:none; }\n  summary:focus-visible { outline:2px solid var(--accent); outline-offset:-2px; }\n  .ntitle { font-weight:600; font-size:14.5px; line-height:1.35; flex:1; letter-spacing:-.005em; }\n  .nmeta { display:flex; gap:5px; align-items:center; flex-shrink:0; }\n  .conf {\n    font-family:var(--mono); font-size:10px; letter-spacing:.07em; text-transform:uppercase;\n    border-radius:2px; padding:2px 6px; border:1px solid;\n  }\n  .conf.high { color:var(--stable); border-color:var(--stable); }\n  .conf.med  { color:var(--monitor); border-color:var(--monitor); }\n  .nbody { padding:0 15px 15px 15px; display:grid; gap:10px; }\n  .nbody p { font-size:14.5px; color:var(--ink-2); max-width:70ch; }\n  .nsrc {\n    font-family:var(--mono); font-size:11.5px; color:var(--ink-3);\n    border-left:2px solid var(--line); padding-left:10px; max-width:74ch; line-height:1.5;\n  }\n  .ngap { font-size:13px; color:var(--warn); font-family:var(--mono); }\n  .ngap.none { color:var(--ink-3); }\n  .typetag {\n    font-family:var(--mono); font-size:10px; letter-spacing:.07em; text-transform:uppercase;\n    color:var(--ink-3); border:1px solid var(--line); border-radius:2px; padding:2px 6px;\n  }\n\n  /* ---------- handoff ---------- */\n  .handoff {\n    background:var(--surface); border:1px solid var(--accent-line); border-radius:4px;\n    padding:22px 22px 20px; box-shadow:var(--shadow); display:grid; gap:16px;\n  }\n  .hgrid { display:grid; gap:14px; grid-template-columns:repeat(auto-fit,minmax(230px,1fr)); }\n  .hitem .k {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--ink-3); display:block; margin-bottom:5px;\n  }\n  .hitem .v { font-size:14.5px; color:var(--ink); }\n  .hitem .v em { color:var(--ink-2); font-style:normal; }\n  .promptbox { position:relative; }\n  .promptbox pre {\n    margin:0; background:var(--ground); border:1px solid var(--line); border-radius:3px;\n    padding:15px 15px 15px; font-family:var(--mono); font-size:12.5px; line-height:1.6;\n    color:var(--ink-2); white-space:pre-wrap; overflow-x:auto;\n  }\n  .copy {\n    position:absolute; top:9px; right:9px; font-family:var(--mono); font-size:11px;\n    background:var(--surface); color:var(--ink-2); border:1px solid var(--line);\n    border-radius:2px; padding:4px 9px; cursor:pointer;\n  }\n  .copy:hover { border-color:var(--accent); color:var(--accent); }\n  .copy:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }\n\n  .scopebox {\n    margin-top:16px; border-left:3px solid var(--warn); background:var(--surface);\n    border-top:1px solid var(--line); border-right:1px solid var(--line); border-bottom:1px solid var(--line);\n    border-radius:0 3px 3px 0; padding:14px 16px; font-size:14px; color:var(--ink-2); max-width:72ch;\n  }\n  .scopebox b { color:var(--ink); font-weight:600; }\n\n  footer {\n    margin-top:56px; border-top:1px solid var(--line); padding-top:16px;\n    font-family:var(--mono); font-size:11px; color:var(--ink-3); letter-spacing:.03em;\n    display:flex; flex-wrap:wrap; gap:8px 18px;\n  }\n  @media (prefers-reduced-motion: reduce) { * { transition:none !important; animation:none !important; } }\n  @media (max-width:620px) {\n    .chips { margin-left:0; }\n    summary { flex-wrap:wrap; }\n  }\n</style>\n\n<div class=\"wrap\">\n\n  <header class=\"mast\">\n    <div class=\"eyebrow\">Agentic Memory · Field Test #1 · Phase R (retrospective)</div>\n    <h1>A behavioral map of how I work with AI</h1>\n    <p class=\"lede\">Built only from five exported conversations. Every claim traces to a named source. This is a symptom diary of a working method — hypothesis-generating, <strong>not diagnostic</strong>, and not a claim about health or neurology.</p>\n    <div class=\"verdictbar\">\n      <span class=\"verdict\">Done-when · <b>Partial pass</b></span>\n      <span class=\"chip\">Method proven</span>\n      <span class=\"chip\">Batch short: 5 of ~50</span>\n      <span class=\"chip\">Orphan claims: 0</span>\n    </div>\n    <div class=\"stats\">\n      <div class=\"stat short\"><span class=\"n\">5</span><span class=\"k\">Conversations</span></div>\n      <div class=\"stat\"><span class=\"n\">19</span><span class=\"k\">Atomic notes</span></div>\n      <div class=\"stat\"><span class=\"n\">5</span><span class=\"k\">Patterns</span></div>\n      <div class=\"stat\"><span class=\"n\">9</span><span class=\"k\">Gaps</span></div>\n      <div class=\"stat\"><span class=\"n\">3</span><span class=\"k\">Act now</span></div>\n      <div class=\"stat\"><span class=\"n\">1/2</span><span class=\"k\">Rounds used</span></div>\n    </div>\n  </header>\n\n  <section id=\"loop\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">The finding, in one picture</div>\n      <h2>The loop I actually run — and the two rounds it wastes</h2>\n    </div>\n    <div class=\"loop\">\n      <div class=\"track\">\n        <div class=\"node\">\n          <span class=\"t\">Engineered prompt</span>\n          <span class=\"s\">schema · formula · guardrails</span>\n        </div>\n        <div class=\"arrow\" aria-hidden=\"true\">→</div>\n        <div class=\"node\">\n          <span class=\"t\">Report arrives</span>\n          <span class=\"s\">prose, no visual</span>\n        </div>\n        <div class=\"arrow\" aria-hidden=\"true\">→</div>\n        <div class=\"node flag\">\n          <span class=\"t\">“Help me visualize this data”</span>\n          <span class=\"s\">verbatim in 3 of 5 · N03</span>\n        </div>\n        <div class=\"arrow\" aria-hidden=\"true\">→</div>\n        <div class=\"node\">\n          <span class=\"t\">Dashboard</span>\n          <span class=\"s\">what was wanted at turn 1</span>\n        </div>\n      </div>\n      <div class=\"returnrail\">\n        <span class=\"returnlab\">“Redo to the perfect output” ×3 — no exit test · N01</span>\n        <div class=\"bar\" aria-hidden=\"true\"></div>\n      </div>\n      <p class=\"loopcap\">Round one is spent asking for something foreseeable. The return arc has no stop condition, because “perfect” was never given an observable test. Both are structural, not effort problems — and both close with a rule, not more work.</p>\n    </div>\n  </section>\n\n  <section id=\"patterns\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Pattern map · click any row to pull its evidence</div>\n      <h2>Five recurring patterns</h2>\n    </div>\n    <div class=\"patterns\" id=\"pcards\"></div>\n  </section>\n\n  <section id=\"fixes\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Stall points → the one-line fix</div>\n      <h2>Where the approach breaks</h2>\n    </div>\n    <div class=\"tablewrap\">\n      <table>\n        <thead>\n          <tr><th style=\"width:32%\">Stall</th><th style=\"width:30%\">Evidence</th><th>Fix</th></tr>\n        </thead>\n        <tbody>\n          <tr class=\"act\"><td>No externalized “done”<span class=\"now\">Act now</span></td><td>C1 pp.16, 21 · N01, N07</td><td>A Done-when test on every task. Highest leverage single change — LOOP OS already carries it.</td></tr>\n          <tr class=\"act\"><td>Un-pre-empted next step<span class=\"now\">Act now</span></td><td>C2 p.10, C4 p.21, C5 p.26 · N03</td><td>Default analytical outputs to <b>report + dashboard</b> in one pass.</td></tr>\n          <tr class=\"act\"><td>Completeness-blind metrics<span class=\"now\">Act now</span></td><td>C2 p.8 vs C4 p.20 · N09</td><td>Print “inputs present: X/Y” beside any composite score.</td></tr>\n          <tr><td>Un-glossed shorthand</td><td>C1 pp.2, 16, 21 · N02, N08</td><td>Six-line glossary in standing instructions: audiovisual = interactive dashboard, and so on.</td></tr>\n          <tr><td>Verification never enters the loop</td><td>C1 pp.16, 21 · N07</td><td>Append a “flagged for verification” list to any citation-bearing output.</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section id=\"evidence\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Evidence · 19 atomic notes · zero orphan claims</div>\n      <h2>Every claim, with its source</h2>\n    </div>\n    <div class=\"filters\" id=\"filters\">\n      <div class=\"fgroup\"><span class=\"flabel\">Type</span>\n        <button class=\"f\" data-k=\"type\" data-v=\"all\" aria-pressed=\"true\">All</button>\n        <button class=\"f\" data-k=\"type\" data-v=\"Process\" aria-pressed=\"false\">Process</button>\n        <button class=\"f\" data-k=\"type\" data-v=\"Content\" aria-pressed=\"false\">Content</button>\n      </div>\n      <div class=\"fgroup\"><span class=\"flabel\">Source</span>\n        <button class=\"f\" data-k=\"src\" data-v=\"all\" aria-pressed=\"true\">All</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C1\" aria-pressed=\"false\">C1</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C2\" aria-pressed=\"false\">C2</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C3\" aria-pressed=\"false\">C3</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C4\" aria-pressed=\"false\">C4</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C5\" aria-pressed=\"false\">C5</button>\n      </div>\n      <span class=\"fstate\" id=\"fstate\">19 of 19</span>\n    </div>\n    <div class=\"notes\" id=\"notes\"></div>\n  </section>\n\n  <section id=\"gaps\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Gap list · what is thin, missing, or unverified</div>\n      <h2>What would make this map trustworthy</h2>\n    </div>\n    <div class=\"tablewrap\">\n      <table>\n        <thead>\n          <tr><th style=\"width:8%\">ID</th><th style=\"width:30%\">Gap</th><th style=\"width:14%\">Severity</th><th>What closes it</th></tr>\n        </thead>\n        <tbody>\n          <tr><td class=\"id\">G1</td><td>5 of ~50 conversations</td><td class=\"sev s-high\"><span class=\"dot\"></span>High</td><td>Export the remaining ~45 and re-run the pipeline.</td></tr>\n          <tr><td class=\"id\">G2</td><td>No 2021–2025 material</td><td class=\"sev s-high\"><span class=\"dot\"></span>High</td><td>Add older exports; sort by real conversation date, not export date.</td></tr>\n          <tr><td class=\"id\">G3</td><td>Topic monoculture — all health</td><td class=\"sev s-high\"><span class=\"dot\"></span>High</td><td>Add ≥10 non-health conversations (legal, finance, workflow).</td></tr>\n          <tr><td class=\"id\">G4</td><td>C3 deliverable truncated</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium</td><td>Re-export C3 including the post-launch research output.</td></tr>\n          <tr><td class=\"id\">G5</td><td>Content notes N15–N18 unverified</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium</td><td>Verify PMIDs and trials against a citation source before any reuse.</td></tr>\n          <tr><td class=\"id\">G6</td><td>Raw CSVs absent</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium</td><td>Attach the WHOOP, Oura and Visible exports so scores can be recomputed.</td></tr>\n          <tr><td class=\"id\">G7</td><td>Self-reported profile unconfirmed</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium</td><td>Confirm against actual records before any clinical use.</td></tr>\n          <tr><td class=\"id\">G8</td><td>Exports show summaries, not full outputs</td><td class=\"sev s-low\"><span class=\"dot\"></span>Low</td><td>Export full assistant message bodies, not collapsed thought-process.</td></tr>\n          <tr><td class=\"id\">G9</td><td>Can’t separate my patterns from the AI’s habits</td><td class=\"sev s-low\"><span class=\"dot\"></span>Low</td><td>Not fixable by more data — keep the Process/Content split so AI behavior stays labeled.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"scopebox\">\n      <b>Do first: G1 + G3 together.</b> The cheapest high-value move is a <em>diverse</em> next batch — some non-health, some older — not more health conversations. That is the direct test of whether these five patterns are “how I think” or only “how I do health analysis.” Until then the map is provisional and health-scoped.\n    </div>\n  </section>\n\n  <section id=\"handoff\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Handoff card · end of Phase R</div>\n      <h2>Where this stops, and what starts next</h2>\n    </div>\n    <div class=\"handoff\">\n      <div class=\"hgrid\">\n        <div class=\"hitem\"><span class=\"k\">Goal</span><span class=\"v\">Turn exported AI history into atomic notes + pattern map + gap list, every claim traceable, feeding a BigQuery/RAG second brain.</span></div>\n        <div class=\"hitem\"><span class=\"k\">Done-when</span><span class=\"v\"><strong>Partial pass.</strong> <em>Three artifacts, zero orphan claims, all gaps named — but on 5 conversations, not ~50.</em></span></div>\n        <div class=\"hitem\"><span class=\"k\">Decisions</span><span class=\"v\"><em>Scoped to what exists. Split Process vs Content notes. Map treated as provisional and health-scoped. Phase P deferred to fresh context by design.</em></span></div>\n        <div class=\"hitem\"><span class=\"k\">Open</span><span class=\"v\"><em>G1–G3 block a representative map. G4–G5 are the data-integrity items. Round 2 of 2 unspent.</em></span></div>\n        <div class=\"hitem\"><span class=\"k\">Pipeline</span><span class=\"v\"><em>Notes map 1:1 to the guide’s <code>documents</code> rows — N-id → document_id, title → title, body → content, confidence and gap → tags. No embeddings generated here. Watson X stays deferred.</em></span></div>\n        <div class=\"hitem\"><span class=\"k\">Do not</span><span class=\"v\"><em>Re-open this thread to improve it. Anti-resonation: add conversations, or run Phase P fresh.</em></span></div>\n      </div>\n      <div>\n        <span class=\"k eyebrow\" style=\"display:block;margin-bottom:7px\">Next prompt — paste into a fresh session</span>\n        <div class=\"promptbox\">\n          <button class=\"copy\" id=\"copybtn\" type=\"button\">Copy</button>\n          <pre id=\"promptext\">Phase P — Prospective, fresh context. Load only 04-HANDOFF.md, 01-ATOMIC-NOTES.md and 02-PATTERN-MAP.md from agentic-memory/field-test-01/. Do not re-read the source PDFs.\n\nFrom the notes and pattern map alone, predict my 3 most likely next prompts or needs. Draft each one loop-shaped (Outcome / Done-when / Rounds), ready to paste. Ground every prediction in a named pattern (P1–P5) or note (N01–N19) — no orphan predictions. Flag anything you are inferring. Then stop and give me a handoff card.</pre>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <footer>\n    <span>Confidence in the map: Medium — patterns multiply-sourced, sample 5/50, one ~2-week window, health only.</span>\n    <span>Generalization beyond health: Low.</span>\n    <span>Behavioral, not clinical.</span>\n  </footer>\n</div>\n\n<script>\n(function () {\n  \"use strict\";\n\n  var PATTERNS = [\n    { id:\"P1\", claim:\"The “perfect output” recursion\",\n      stall:\"Corrections demand an untestable ideal and loop with no exit — “done” was never defined observably.\",\n      notes:[\"N01\",\"N07\"], conf:\"High\" },\n    { id:\"P2\", claim:\"Shorthand the AI must decode over rounds\",\n      stall:\"“Audiovisuals”, “cognitive wish” carry stable intent, but interpretation lags 2–3 rounds.\",\n      notes:[\"N02\",\"N08\"], conf:\"High\" },\n    { id:\"P3\", claim:\"The predictable second step\",\n      stall:\"Analysis is always followed by “Help me visualize this data” — an entire round spent on the foreseeable.\",\n      notes:[\"N03\"], conf:\"High\" },\n    { id:\"P4\", claim:\"Heavy front-loaded scaffolding, versioned\",\n      stall:\"Exact schemas, formulas and guardrails, maintained v1 → v2. High authoring effort, brittle to missing inputs.\",\n      notes:[\"N04\",\"N05\",\"N12\"], conf:\"Medium\" },\n    { id:\"P5\", claim:\"Answer fragility on incomplete data\",\n      stall:\"Headline metric swings ~1 point on same-day data gaps. Same question, two numbers, no completeness flag.\",\n      notes:[\"N09\",\"N10\"], conf:\"Medium\" }\n  ];\n\n  var NOTES = [\n    { id:\"N01\", type:\"Process\", src:[\"C1\"], conf:\"High\",\n      title:\"I re-issue a near-identical “perfect output / red-team” prompt until satisfied, with no stated stop condition\",\n      body:\"The same meta-instruction fires at least three times in one thread. Each firing makes the AI rebuild from scratch. Because “perfect” and “cognitive wish” are never given an observable test, the loop has no exit — it can recurse indefinitely. This is the exact failure the Done-when and anti-resonation rules are built to stop.\",\n      source:\"C1 pp. 16 & 21 — the sentence appears verbatim twice, after an initial “redo”.\",\n      why:\"Identical prompt text visible on two pages.\", gap:\"\" },\n    { id:\"N02\", type:\"Process\", src:[\"C1\"], conf:\"High\",\n      title:\"“Audiovisuals” is my shorthand for “make it interactive, not prose” — the AI needed 2–3 rounds to decode it\",\n      body:\"The word escalates across turns as the AI keeps returning text. It eventually decodes to “build a dashboard”, which ends the escalation. The intent was stable from turn 1; only the interpretation lagged. A one-word gloss in standing instructions would collapse this to a single round.\",\n      source:\"C1 p.2 “make sure the audiovisuals are always there” → p.16 “Add audiovisuals too” → p.21 “Always use Audiovisuals in the output”.\",\n      why:\"High for the recurrence; Medium for the intended meaning, inferred from the dashboard being accepted (p.19).\",\n      gap:\"No explicit line confirming “a dashboard is what I meant”.\" },\n    { id:\"N03\", type:\"Process\", src:[\"C2\",\"C4\",\"C5\"], conf:\"High\",\n      title:\"“Help me visualize this data” is my reflexive second move — verbatim across three separate conversations\",\n      body:\"The sequence is stable: request analysis → receive report → immediately ask for a visualization. Predictable enough to pre-empt: delivering report and dashboard in the first pass removes an entire round in about 60% of the sampled threads.\",\n      source:\"C2 p.10, C4 p.21, C5 p.26 — identical string in all three.\",\n      why:\"Identical string, three independent exports.\", gap:\"\" },\n    { id:\"N04\", type:\"Process\", src:[\"C2\",\"C4\"], conf:\"High\",\n      title:\"I front-load heavy scaffolding — exact schemas, formulas, anti-fabrication rules — to constrain the AI before it runs\",\n      body:\"Prompts specify CSV column names, parse code, a 5-node scoring formula, tiered alert thresholds, a contraindicated-drug list, and rules such as “NEVER fabricate” and “cite file + column”. I engineer the guardrails myself rather than trusting defaults. Buys precision; high effort and brittle — see N09.\",\n      source:\"C2 pp.2–4, C4 pp.2–15.\", why:\"The scaffolding is the bulk of both conversations.\", gap:\"\" },\n    { id:\"N05\", type:\"Process\", src:[\"C4\",\"C2\"], conf:\"High\",\n      title:\"I version my master-prompts — the nonadherence prompt is explicitly “v2.0 (Red-Team Validated)”\",\n      body:\"C4 restates C2’s patient context, data schemas and Loop Score formula in a cleaner, numbered, more defensive form and labels itself v2.0. Prompts are treated as maintained software artifacts, not one-off messages — the reuse pattern the BigQuery plan is meant to institutionalize.\",\n      source:\"C4 p.2 title block vs C2 p.2.\", why:\"Version label and near-duplicate structure both visible.\", gap:\"\" },\n    { id:\"N06\", type:\"Process\", src:[\"C3\"], conf:\"High\",\n      title:\"When asked clarifying questions, I delegate the decision back rather than specifying\",\n      body:\"Faced with three clarifying questions — budget, use pattern, coverage — I removed two constraints (“cost no object”, “max wear”) and handed the third back (“you recommend”). Implication: clarifying questions are often friction. Design consequence — prefer propose-then-confirm over ask-then-wait.\",\n      source:\"C3 p.6 — answers quoted verbatim: “co0st no matter”, “as often as I can”, “I want you to recommend the correct answer”.\",\n      why:\"Answers quoted verbatim.\", gap:\"Single conversation; may not generalize.\" },\n    { id:\"N07\", type:\"Process\", src:[\"C1\"], conf:\"Medium\",\n      title:\"My corrections target form and depth, not factual errors — I rarely dispute a specific claim\",\n      body:\"Across the visible correction turns, none says “that number is wrong” or “that citation is off”. Every correction pushes for better rendering or a deeper pass. Strength: fast to a usable artifact. Latent risk: the correction budget never lands on fact-checking, so errors in the content notes below would survive review.\",\n      source:\"C1 pp.16, 21.\", why:\"Inferred from absence of factual disputes in a small visible set.\",\n      gap:\"Only C1 contains explicit correction turns.\" },\n    { id:\"N08\", type:\"Process\", src:[\"C3\"], conf:\"High\",\n      title:\"I frame the AI as a cognitive layer for a verbal thinker, not merely a tool\",\n      body:\"The stated self-model is consistent: language in, finished cognition out; the AI does the translation to the technical layer. Same premise as the standing operating instructions — the operating system is itself a compensatory response to how I think.\",\n      source:\"C3 p.2 — “the expert executor of prompts which forms an additional layer or transformer… aiding a verbal thinker to maximize AI use”.\",\n      why:\"Quoted, and echoed by the session’s own preamble.\", gap:\"\" },\n    { id:\"N09\", type:\"Process\", src:[\"C2\",\"C4\"], conf:\"High\",\n      title:\"Same data, same date, same formula produced two different Loop Scores — 6.7 vs 5.7\",\n      body:\"Both target 2026-03-15, the same person, the same 5-node formula. The scores diverge mainly on the Inflammatory/PEM node, which depends on same-day symptom logging that was partially absent. A headline metric that swings about a point on data completeness is fragile; it needs an explicit completeness flag beside the score.\",\n      source:\"C2 p.8 (LS 6.7, “only because today’s Visible entries are incomplete”) vs C4 p.20 (LS 5.7, WARNING).\",\n      why:\"High for the two numbers; Medium for pinning the delta to one node.\",\n      gap:\"Raw CSVs not in session — cannot recompute.\" },\n    { id:\"N10\", type:\"Content\", src:[\"C2\",\"C4\"], conf:\"High\",\n      title:\"Across both clinical reports the AI independently ranks propranolol non-adherence as the #1 lever\",\n      body:\"Both reports surface the same dominant real-world lever: adherence, reported at 38% / 20% / eight consecutive missed doses. It is the most stable finding the data produces. Recorded here as a recurring signal in the corpus — not as a medical recommendation.\",\n      source:\"C2 p.9, C4 p.20.\", why:\"High that both reports ranked it first.\",\n      gap:\"Adherence figures are AI-reported from CSVs not present; unverified.\" },\n    { id:\"N11\", type:\"Process\", src:[\"C1\"], conf:\"High\",\n      title:\"I am building the meta-system that would automate the n-of-1 analysis I keep running by hand\",\n      body:\"CNN for feature extraction from raw wearable inputs, RNN for longitudinal memory, RL for experiment selection — each layer mapped to a real research system. The through-line across all five conversations: turn personal biometric data into a self-improving retrieval and decision system. Same ambition as this field test.\",\n      source:\"C1 pp.3–4, 9–15.\", why:\"Architecture is spelled out.\",\n      gap:\"Aspirational design; no evidence any of it is deployed.\" },\n    { id:\"N12\", type:\"Content\", src:[\"C4\",\"C2\"], conf:\"High\",\n      title:\"Substrate: the 5-node Loop Score is my own composite metric, defined by explicit formula\",\n      body:\"LS = (Autonomic + Sleep + Inflammatory/PEM + Pharmacologic + Deconditioning) / 15 × 10, each node 0–3. Bands: 0–3 stable, 3–5 monitoring, 5–7 warning, 7–10 critical. An invented instrument for compressing multi-stream data into one number — a durable definition worth persisting to the wiki.\",\n      source:\"C4 pp.5–6, C2 p.3.\", why:\"Formula quoted.\", gap:\"Validity of the instrument is out of scope here.\" },\n    { id:\"N13\", type:\"Content\", src:[\"C2\",\"C4\"], conf:\"High\",\n      title:\"Substrate: self-reported clinical profile stated in-prompt — declared, not confirmed\",\n      body:\"Age 32; ICD implanted Feb 2023 with follow-up overdue; Long COVID, POTS, Brugada (SCN5A suspected), DM2, active VZV, ME-CFS overlap; baseline over 166 days HRV ~20 ms, RHR ~84 bpm, recovery 36%, sleep ~5 h. User-supplied context, not a verified record.\",\n      source:\"C2 p.2, C4 p.2.\", why:\"High that it is stated.\", gap:\"Unverified medical history — treat as declared.\" },\n    { id:\"N14\", type:\"Content\", src:[\"C1\"], conf:\"High\",\n      title:\"Substrate: behavioral and dietary identity surfaced from my own files\",\n      body:\"Halal 100%, intermittent fasting ~35% of days, magnesium and L-theanine, ~0% alcohol, ~12% caffeine. Corpus size: WHOOP 277 days, Oura 62 days, 1,399 journal entries across 47 unique questions — named as the reinforcement-learning training signal for the second-brain system.\",\n      source:\"C1 pp.23–25.\", why:\"High that the AI reported them; Medium that figures are exact.\",\n      gap:\"Underlying files not in session.\" },\n    { id:\"N15\", type:\"Content\", src:[\"C1\"], conf:\"Medium\",\n      title:\"Substrate: meal decode headline — peanut butter blunts the spike about 30%\",\n      body:\"Bread + Nutella + peanut butter ≈ 525 kcal at roughly 49/41/10 fat/carb/protein; Nutella ~57% sugar by weight; peanut butter blunts the glucose spike about 30%, attributed to Niederhoffer 2018. Optimal protocol offered: morning, peanut-butter-first, whole-wheat.\",\n      source:\"C1 pp.4–6.\", why:\"AI synthesis with PMIDs, not independently checked here.\",\n      gap:\"Citations unverified in this session.\" },\n    { id:\"N16\", type:\"Content\", src:[\"C5\"], conf:\"Medium\",\n      title:\"Substrate: POTS pharmacotherapy ranking\",\n      body:\"The synthesis ranks ivabradine and low-dose propranolol as strongest for heart-rate control, and guanfacine as the best dual POTS + ADHD agent, citing 85% response in hyperadrenergic POTS. Fludrocortisone weak; midodrine, salt and compression complementary.\",\n      source:\"C5 pp.5–7, 16.\", why:\"Tagged peer-reviewed, unverified here.\", gap:\"Citations unverified.\" },\n    { id:\"N17\", type:\"Content\", src:[\"C5\"], conf:\"Medium\",\n      title:\"Substrate: GLP-1 risk thesis — flagged high-risk for this profile\",\n      body:\"GLP-1 agonists raise heart rate through a sinus-node mechanism ivabradine cannot block, and suppress HRV by about 6 ms — meaningful from an already-low baseline. Net position in the synthesis: defer pending the named trials.\",\n      source:\"C5 pp.11–12, 22–24.\", why:\"Mechanistic claims tagged peer-reviewed, unverified here.\",\n      gap:\"Citations unverified.\" },\n    { id:\"N18\", type:\"Content\", src:[\"C5\"], conf:\"Medium\",\n      title:\"Substrate: MCAS-as-driver thesis plus an empiric antihistamine trial\",\n      body:\"Mast Cell Activation Syndrome — an over-reactive mast-cell condition — is framed as a likely under-diagnosed driver of POTS via a mast-cell to sympathetic feedback loop. An empiric H1/H2 antihistamine trial is presented as low-risk, high-reward.\",\n      source:\"C5 pp.18–20.\", why:\"Tagged peer-reviewed, unverified here.\",\n      gap:\"Citations unverified; a diagnostic hypothesis, not a diagnosis.\" },\n    { id:\"N19\", type:\"Process\", src:[\"C3\"], conf:\"High\",\n      title:\"Gap-note: C3’s actual deliverable is absent from the export\",\n      body:\"The compression-wrap conversation is captured only up to the moment research launches — no product list, no recommendation, no pressures or sizing. Any downstream claim about what I was told regarding compression must come from C5’s corroborating evidence, not from C3.\",\n      source:\"C3 p.6 — thread ends at the research launch.\", why:\"The truncation point is visible.\",\n      gap:\"The deliverable itself is the gap.\" }\n  ];\n\n  var state = { type:\"all\", src:\"all\", pattern:null };\n\n  function esc(s) {\n    return String(s).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\");\n  }\n\n  /* ---- pattern cards ---- */\n  var pwrap = document.getElementById(\"pcards\");\n  PATTERNS.forEach(function (p) {\n    var b = document.createElement(\"button\");\n    b.type = \"button\";\n    b.className = \"pcard\";\n    b.setAttribute(\"aria-pressed\", \"false\");\n    b.dataset.p = p.id;\n    b.innerHTML =\n      ''<div class=\"prow\"><span class=\"id\">'' + p.id + ''</span>'' +\n      ''<span class=\"claim\">'' + esc(p.claim) + ''</span>'' +\n      ''<span class=\"chips\"><span class=\"chip\">'' + p.notes.join(\" · \") + ''</span>'' +\n      ''<span class=\"chip\">'' + p.conf + ''</span></span></div>'' +\n      ''<div class=\"stall\">'' + esc(p.stall) + ''</div>'';\n    b.addEventListener(\"click\", function () {\n      state.pattern = (state.pattern === p.id) ? null : p.id;\n      syncPatterns();\n      render();\n      if (state.pattern) {\n        document.getElementById(\"evidence\").scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n      }\n    });\n    pwrap.appendChild(b);\n  });\n\n  function syncPatterns() {\n    Array.prototype.forEach.call(pwrap.children, function (el) {\n      el.setAttribute(\"aria-pressed\", el.dataset.p === state.pattern ? \"true\" : \"false\");\n    });\n  }\n\n  /* ---- filters ---- */\n  var fbtns = document.querySelectorAll(\"#filters .f\");\n  Array.prototype.forEach.call(fbtns, function (btn) {\n    btn.addEventListener(\"click\", function () {\n      state[btn.dataset.k] = btn.dataset.v;\n      state.pattern = null;\n      syncPatterns();\n      Array.prototype.forEach.call(fbtns, function (o) {\n        if (o.dataset.k === btn.dataset.k) {\n          o.setAttribute(\"aria-pressed\", o === btn ? \"true\" : \"false\");\n        }\n      });\n      render();\n    });\n  });\n\n  /* ---- notes ---- */\n  var nwrap = document.getElementById(\"notes\");\n  var fstate = document.getElementById(\"fstate\");\n\n  function visible(n) {\n    if (state.pattern) {\n      var p = PATTERNS.filter(function (x) { return x.id === state.pattern; })[0];\n      return p.notes.indexOf(n.id) !== -1;\n    }\n    if (state.type !== \"all\" && n.type !== state.type) { return false; }\n    if (state.src !== \"all\" && n.src.indexOf(state.src) === -1) { return false; }\n    return true;\n  }\n\n  function render() {\n    var shown = NOTES.filter(visible);\n    nwrap.innerHTML = shown.map(function (n) {\n      var confCls = n.conf === \"High\" ? \"high\" : \"med\";\n      return ''<details class=\"note'' + (state.pattern ? \" lit\" : \"\") + ''\"'' + (state.pattern ? \" open\" : \"\") + ''>'' +\n        ''<summary><span class=\"id\">'' + n.id + ''</span>'' +\n        ''<span class=\"ntitle\">'' + esc(n.title) + ''</span>'' +\n        ''<span class=\"nmeta\"><span class=\"typetag\">'' + n.type + ''</span>'' +\n        ''<span class=\"conf '' + confCls + ''\">'' + n.conf + ''</span></span></summary>'' +\n        ''<div class=\"nbody\"><p>'' + esc(n.body) + ''</p>'' +\n        ''<div class=\"nsrc\">Source · '' + esc(n.source) + ''<br>Confidence · '' + n.conf + '' — '' + esc(n.why) + ''</div>'' +\n        ''<div class=\"ngap'' + (n.gap ? \"\" : \" none\") + ''\">Gap · '' + esc(n.gap || \"none\") + ''</div></div></details>'';\n    }).join(\"\");\n    fstate.textContent = state.pattern\n      ? shown.length + \" supporting \" + state.pattern + \" — click \" + state.pattern + \" again to clear\"\n      : shown.length + \" of \" + NOTES.length;\n  }\n\n  render();\n\n  /* ---- copy ---- */\n  var btn = document.getElementById(\"copybtn\");\n  btn.addEventListener(\"click\", function () {\n    var text = document.getElementById(\"promptext\").textContent;\n    var done = function () {\n      btn.textContent = \"Copied\";\n      setTimeout(function () { btn.textContent = \"Copy\"; }, 1600);\n    };\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(text).then(done, function () { btn.textContent = \"Select manually\"; });\n    } else {\n      btn.textContent = \"Select manually\";\n    }\n  });\n})();\n</script>\n", "file_path": "/home/user/claude-/agentic-memory/field-test-01/field-test-01.html"}');
