2	<style>
3	  :root {
4	    --ground:#EFF2F3; --surface:#FFFFFF; --surface-2:#E5EAEC; --line:#C9D4D8;
5	    --ink:#131E26; --ink-2:#465A66; --ink-3:#71868F;
6	    --accent:#0D6E68; --accent-soft:#D6EAE8; --accent-line:#8FC7C2;
