18	      --accent:#4FBFB4; --accent-soft:#12332F; --accent-line:#2C5F5A; --on-accent:#08110F;
19	      --stable:#5FB483; --monitor:#CBA13C; --warn:#DD8850; --crit:#D96A6A;
20	      --shadow:0 1px 2px rgba(0,0,0,.4), 0 8px 24px -16px rgba(0,0,0,.7);
21	    }
22	  }
23	  :root[data-theme="dark"] {
24	    --ground:#0C1418; --surface:#121D23; --surface-2:#1A2932; --line:#26383F;
