INSERT INTO blocks (block_id, turn_uuid, turn_no, seq, role, kind, chars, tool_name, tool_use_id, is_error, redacted, signature_sha256, signature_len, privacy_zone, zone_reason, zone_match, text) VALUES (94, '92107c84-08b4-4b30-9330-4d008f566ba9', 71, 0, 'assistant', 'thinking', 0, NULL, NULL, 0, 1, 'd81c382f86f5618029c6efbfcc174c200056102c92549d9c56143d16bffb60d2', 1872, 'Private work', 'session-internal', '', '');
INSERT INTO blocks (block_id, turn_uuid, turn_no, seq, role, kind, chars, tool_name, tool_use_id, is_error, redacted, signature_sha256, signature_len, privacy_zone, zone_reason, zone_match, text) VALUES (95, '92107c84-08b4-4b30-9330-4d008f566ba9', 71, 1, 'assistant', 'tool_use', 62936, 'Write', 'toolu_019hjtcaBKr6BT89rVeMPBLT', 0, 0, NULL, NULL, 'Confidential', 'litigation', 'affidavit', '{"content": "<title>Field Test #1 — How I Work With AI</title>\n<style>\n  :root {\n    --ground:#EFF2F3; --surface:#FFFFFF; --surface-2:#E5EAEC; --line:#C9D4D8;\n    --ink:#131E26; --ink-2:#465A66; --ink-3:#71868F;\n    --accent:#0D6E68; --accent-soft:#D6EAE8; --accent-line:#8FC7C2; --on-accent:#FFFFFF;\n    --stable:#2E7D53; --monitor:#8E6A10; --warn:#B0511C; --crit:#962727;\n    --shadow:0 1px 2px rgba(19,30,38,.06), 0 8px 24px -16px rgba(19,30,38,.28);\n    --serif: \"Iowan Old Style\",\"Palatino Linotype\",Palatino,\"Book Antiqua\",Georgia,serif;\n    --sans: system-ui,-apple-system,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n    --mono: ui-monospace,SFMono-Regular,\"SF Mono\",Menlo,Consolas,\"Liberation Mono\",monospace;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --ground:#0C1418; --surface:#121D23; --surface-2:#1A2932; --line:#26383F;\n      --ink:#E3EDF0; --ink-2:#9DB2BC; --ink-3:#7A929D;\n      --accent:#4FBFB4; --accent-soft:#12332F; --accent-line:#2C5F5A; --on-accent:#08110F;\n      --stable:#5FB483; --monitor:#CBA13C; --warn:#DD8850; --crit:#D96A6A;\n      --shadow:0 1px 2px rgba(0,0,0,.4), 0 8px 24px -16px rgba(0,0,0,.7);\n    }\n  }\n  :root[data-theme=\"dark\"] {\n    --ground:#0C1418; --surface:#121D23; --surface-2:#1A2932; --line:#26383F;\n    --ink:#E3EDF0; --ink-2:#9DB2BC; --ink-3:#7A929D;\n    --accent:#4FBFB4; --accent-soft:#12332F; --accent-line:#2C5F5A; --on-accent:#08110F;\n    --stable:#5FB483; --monitor:#CBA13C; --warn:#DD8850; --crit:#D96A6A;\n    --shadow:0 1px 2px rgba(0,0,0,.4), 0 8px 24px -16px rgba(0,0,0,.7);\n  }\n  :root[data-theme=\"light\"] {\n    --ground:#EFF2F3; --surface:#FFFFFF; --surface-2:#E5EAEC; --line:#C9D4D8;\n    --ink:#131E26; --ink-2:#465A66; --ink-3:#71868F;\n    --accent:#0D6E68; --accent-soft:#D6EAE8; --accent-line:#8FC7C2; --on-accent:#FFFFFF;\n    --stable:#2E7D53; --monitor:#8E6A10; --warn:#B0511C; --crit:#962727;\n    --shadow:0 1px 2px rgba(19,30,38,.06), 0 8px 24px -16px rgba(19,30,38,.28);\n  }\n\n  * { box-sizing: border-box; }\n  body {\n    margin:0; background:var(--ground); color:var(--ink);\n    font-family:var(--sans); font-size:16px; line-height:1.55;\n    -webkit-font-smoothing:antialiased;\n  }\n  .wrap { max-width:960px; margin:0 auto; padding:0 20px 80px; }\n  section { padding-top:52px; }\n  h1,h2,h3 { text-wrap:balance; margin:0; }\n  p { margin:0; }\n\n  .eyebrow {\n    font-family:var(--mono); font-size:11px; letter-spacing:.13em;\n    text-transform:uppercase; color:var(--ink-3);\n  }\n  .id { font-family:var(--mono); font-size:12px; color:var(--accent); font-weight:600; }\n  .lede { font-size:16px; color:var(--ink-2); max-width:64ch; }\n\n  header.mast { padding:56px 0 0; }\n  .mast h1 {\n    font-family:var(--serif); font-weight:600; letter-spacing:-.015em;\n    font-size:clamp(30px,5.2vw,46px); line-height:1.08; margin:14px 0 12px; max-width:20ch;\n  }\n  .verdictbar { display:flex; flex-wrap:wrap; align-items:center; gap:10px; margin-top:22px; }\n  .verdict {\n    display:inline-flex; align-items:baseline; gap:8px;\n    font-family:var(--mono); font-size:12px; letter-spacing:.08em; text-transform:uppercase;\n    background:var(--accent-soft); color:var(--accent);\n    border:1px solid var(--accent-line); border-radius:2px; padding:6px 11px; font-weight:600;\n  }\n  .stats {\n    display:grid; grid-template-columns:repeat(auto-fit,minmax(100px,1fr));\n    gap:1px; background:var(--line); border:1px solid var(--line);\n    margin-top:24px; border-radius:3px; overflow:hidden;\n  }\n  .stat { background:var(--surface); padding:13px 14px; }\n  .stat .n {\n    font-family:var(--mono); font-size:23px; font-weight:600; letter-spacing:-.02em;\n    font-variant-numeric:tabular-nums; display:block; line-height:1.1;\n  }\n  .stat .k {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--ink-3); margin-top:5px; display:block;\n  }\n  .stat.short .n { color:var(--warn); }\n  .stat.gain .n { color:var(--accent); }\n\n  .shead { border-top:1px solid var(--line); padding-top:16px; margin-bottom:22px; }\n  .shead h2 {\n    font-family:var(--serif); font-weight:600; font-size:clamp(21px,3vw,27px);\n    letter-spacing:-.01em; margin:8px 0 8px; line-height:1.2;\n  }\n\n  /* mirrored-stall diagram */\n  .mirror {\n    background:var(--surface); border:1px solid var(--line); border-radius:4px;\n    padding:24px 22px 20px; box-shadow:var(--shadow);\n  }\n  .panes { display:grid; gap:16px; grid-template-columns:repeat(auto-fit,minmax(290px,1fr)); }\n  .pane { border:1px solid var(--line); border-radius:3px; padding:15px 16px; background:var(--surface-2); }\n  .pane h3 {\n    font-size:14px; font-weight:600; margin-bottom:3px;\n  }\n  .pane .who { font-family:var(--mono); font-size:10.5px; letter-spacing:.09em; text-transform:uppercase; color:var(--ink-3); }\n  .cycle { display:flex; flex-direction:column; gap:6px; margin:13px 0 12px; }\n  .beat {\n    font-family:var(--mono); font-size:12px; background:var(--surface);\n    border:1px solid var(--line); border-radius:2px; padding:7px 10px; color:var(--ink-2);\n  }\n  .beat.loopmark { border-color:var(--crit); color:var(--crit); font-weight:600; }\n  .beat.dead { border-style:dashed; border-color:var(--crit); color:var(--crit); }\n  .cost {\n    font-family:var(--mono); font-size:11.5px; color:var(--crit);\n    border-top:1px solid var(--line); padding-top:9px;\n  }\n  .fixline {\n    margin-top:16px; padding:13px 15px; border-left:3px solid var(--accent);\n    background:var(--accent-soft); border-radius:0 3px 3px 0; font-size:14.5px; color:var(--ink);\n  }\n  .fixline b { font-weight:600; }\n\n  /* pattern cards */\n  .patterns { display:grid; gap:9px; }\n  .pcard {\n    width:100%; text-align:left; font:inherit; color:inherit; cursor:pointer;\n    background:var(--surface); border:1px solid var(--line); border-left:3px solid var(--accent-line);\n    border-radius:3px; padding:14px 16px; display:grid; gap:6px;\n    transition:border-color .14s ease, background .14s ease;\n  }\n  .pcard:hover { border-left-color:var(--accent); }\n  .pcard[aria-pressed=\"true\"] { border-left-color:var(--accent); background:var(--accent-soft); }\n  .pcard:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }\n  .prow { display:flex; align-items:baseline; gap:10px; flex-wrap:wrap; }\n  .pcard .claim { font-weight:600; font-size:15.5px; letter-spacing:-.005em; }\n  .pcard .stall { font-size:13.5px; color:var(--ink-2); }\n  .chips { display:flex; gap:5px; flex-wrap:wrap; margin-left:auto; }\n  .chip {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.04em;\n    border:1px solid var(--line); border-radius:2px; padding:2px 6px; color:var(--ink-3);\n    background:var(--ground);\n  }\n  .chip.x { color:var(--stable); border-color:var(--stable); }\n  .chip.new { color:var(--accent); border-color:var(--accent-line); }\n\n  .tablewrap { overflow-x:auto; border:1px solid var(--line); border-radius:3px; background:var(--surface); }\n  table { border-collapse:collapse; width:100%; min-width:600px; font-size:14px; }\n  th, td { text-align:left; padding:11px 14px; border-bottom:1px solid var(--line); vertical-align:top; }\n  th {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--ink-3); font-weight:600; background:var(--surface-2);\n  }\n  tbody tr:last-child td { border-bottom:none; }\n  td.sev { font-family:var(--mono); font-size:11px; white-space:nowrap; }\n  .dot { display:inline-block; width:7px; height:7px; border-radius:50%; margin-right:7px; vertical-align:1px; }\n  .s-high .dot { background:var(--crit); } .s-high { color:var(--crit); }\n  .s-med .dot  { background:var(--warn); } .s-med  { color:var(--warn); }\n  .s-low .dot  { background:var(--ink-3); } .s-low { color:var(--ink-3); }\n  tr.act td:first-child { box-shadow:inset 3px 0 0 var(--accent); }\n  .now, .tag {\n    font-family:var(--mono); font-size:10px; letter-spacing:.08em; text-transform:uppercase;\n    border-radius:2px; padding:1px 5px; margin-left:8px; white-space:nowrap; border:1px solid;\n  }\n  .now { color:var(--accent); border-color:var(--accent-line); }\n  .tag { color:var(--ink-3); border-color:var(--line); }\n\n  /* evidence */\n  .filters { display:flex; flex-wrap:wrap; gap:6px; align-items:center; margin-bottom:14px; }\n  .fgroup { display:flex; gap:4px; align-items:center; flex-wrap:wrap; }\n  .flabel {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--ink-3); margin-right:3px;\n  }\n  .f {\n    font-family:var(--mono); font-size:11.5px; cursor:pointer; color:var(--ink-2);\n    background:var(--surface); border:1px solid var(--line); border-radius:2px; padding:4px 9px;\n    transition:all .12s ease;\n  }\n  .f:hover { border-color:var(--accent-line); color:var(--ink); }\n  .f[aria-pressed=\"true\"] { background:var(--accent); border-color:var(--accent); color:var(--on-accent); }\n  .f:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }\n  .fstate {\n    font-family:var(--mono); font-size:11.5px; color:var(--ink-3); margin-left:auto;\n    font-variant-numeric:tabular-nums;\n  }\n  .notes { display:grid; gap:7px; }\n  details.note { background:var(--surface); border:1px solid var(--line); border-radius:3px; }\n  details.note[open] { border-color:var(--accent-line); }\n  details.note.lit { box-shadow:inset 3px 0 0 var(--accent); }\n  summary { cursor:pointer; padding:12px 15px; display:flex; gap:11px; align-items:baseline; list-style:none; }\n  summary::-webkit-details-marker { display:none; }\n  summary:focus-visible { outline:2px solid var(--accent); outline-offset:-2px; }\n  .ntitle { font-weight:600; font-size:14.5px; line-height:1.35; flex:1; letter-spacing:-.005em; }\n  .nmeta { display:flex; gap:5px; align-items:center; flex-shrink:0; flex-wrap:wrap; }\n  .conf {\n    font-family:var(--mono); font-size:10px; letter-spacing:.07em; text-transform:uppercase;\n    border-radius:2px; padding:2px 6px; border:1px solid;\n  }\n  .conf.high { color:var(--stable); border-color:var(--stable); }\n  .conf.med  { color:var(--monitor); border-color:var(--monitor); }\n  .typetag {\n    font-family:var(--mono); font-size:10px; letter-spacing:.07em; text-transform:uppercase;\n    color:var(--ink-3); border:1px solid var(--line); border-radius:2px; padding:2px 6px;\n  }\n  .nbody { padding:0 15px 15px 15px; display:grid; gap:10px; }\n  .nbody p { font-size:14.5px; color:var(--ink-2); max-width:72ch; }\n  .nsrc {\n    font-family:var(--mono); font-size:11.5px; color:var(--ink-3);\n    border-left:2px solid var(--line); padding-left:10px; max-width:76ch; line-height:1.5;\n  }\n  .ngap { font-size:13px; color:var(--warn); font-family:var(--mono); }\n  .ngap.none { color:var(--ink-3); }\n\n  /* phase P */\n  .pred {\n    background:var(--surface); border:1px solid var(--line); border-radius:3px;\n    padding:17px 18px; display:grid; gap:11px; margin-bottom:10px;\n  }\n  .pred h3 { font-size:16px; font-weight:600; letter-spacing:-.005em; }\n  .pred .why { font-size:14px; color:var(--ink-2); max-width:74ch; }\n  .promptbox { position:relative; }\n  .promptbox pre {\n    margin:0; background:var(--ground); border:1px solid var(--line); border-radius:3px;\n    padding:15px 15px; font-family:var(--mono); font-size:12.5px; line-height:1.6;\n    color:var(--ink-2); white-space:pre-wrap; overflow-x:auto;\n  }\n  .copy {\n    position:absolute; top:9px; right:9px; font-family:var(--mono); font-size:11px;\n    background:var(--surface); color:var(--ink-2); border:1px solid var(--line);\n    border-radius:2px; padding:4px 9px; cursor:pointer;\n  }\n  .copy:hover { border-color:var(--accent); color:var(--accent); }\n  .copy:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }\n\n  .handoff {\n    background:var(--surface); border:1px solid var(--accent-line); border-radius:4px;\n    padding:22px; box-shadow:var(--shadow); display:grid; gap:15px;\n  }\n  .hgrid { display:grid; gap:14px; grid-template-columns:repeat(auto-fit,minmax(230px,1fr)); }\n  .hitem .k {\n    font-family:var(--mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;\n    color:var(--ink-3); display:block; margin-bottom:5px;\n  }\n  .hitem .v { font-size:14.5px; }\n  .hitem .v em { color:var(--ink-2); font-style:normal; }\n\n  .scopebox {\n    margin-top:16px; border-left:3px solid var(--warn); background:var(--surface);\n    border-top:1px solid var(--line); border-right:1px solid var(--line); border-bottom:1px solid var(--line);\n    border-radius:0 3px 3px 0; padding:14px 16px; font-size:14px; color:var(--ink-2); max-width:74ch;\n  }\n  .scopebox b { color:var(--ink); font-weight:600; }\n\n  footer {\n    margin-top:56px; border-top:1px solid var(--line); padding-top:16px;\n    font-family:var(--mono); font-size:11px; color:var(--ink-3); letter-spacing:.03em;\n    display:flex; flex-wrap:wrap; gap:8px 18px;\n  }\n  @media (prefers-reduced-motion: reduce) { * { transition:none !important; } }\n  @media (max-width:620px) { .chips { margin-left:0; } summary { flex-wrap:wrap; } }\n</style>\n\n<div class=\"wrap\">\n\n  <header class=\"mast\">\n    <div class=\"eyebrow\">Agentic Memory · Field Test #1 · Round 2 — Phase R + Phase P</div>\n    <h1>A behavioural map of how I work with AI</h1>\n    <p class=\"lede\">Eight exported conversations, two platforms, two domains, five months apart. Every claim traces to a named source. This is a symptom diary of a working method — hypothesis-generating, <strong>not diagnostic</strong>, and not a claim about health, neurology, or the merits of any legal matter.</p>\n    <div class=\"verdictbar\">\n      <span class=\"verdict\">Done-when · <b>Partial pass</b></span>\n      <span class=\"chip x\">Cross-checked on 2 platforms</span>\n      <span class=\"chip\">Batch short: 8 of ~50</span>\n      <span class=\"chip\">Orphan claims: 0</span>\n    </div>\n    <div class=\"stats\">\n      <div class=\"stat short\"><span class=\"n\">8</span><span class=\"k\">Conversations</span></div>\n      <div class=\"stat gain\"><span class=\"n\">2</span><span class=\"k\">Platforms</span></div>\n      <div class=\"stat gain\"><span class=\"n\">2</span><span class=\"k\">Domains</span></div>\n      <div class=\"stat\"><span class=\"n\">34</span><span class=\"k\">Atomic notes</span></div>\n      <div class=\"stat\"><span class=\"n\">7</span><span class=\"k\">Patterns</span></div>\n      <div class=\"stat\"><span class=\"n\">12</span><span class=\"k\">Gaps</span></div>\n      <div class=\"stat\"><span class=\"n\">2/2</span><span class=\"k\">Rounds used</span></div>\n    </div>\n  </header>\n\n  <section id=\"finding\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">The finding, in one picture</div>\n      <h2>The loop stalls whenever neither side holds a stop rule</h2>\n    </div>\n    <div class=\"mirror\">\n      <div class=\"panes\">\n        <div class=\"pane\">\n          <span class=\"who\">My side · no exit test</span>\n          <h3>“Redo it to the perfect output”</h3>\n          <div class=\"cycle\">\n            <div class=\"beat\">Engineered prompt · schema, formula, guardrails</div>\n            <div class=\"beat\">Report arrives</div>\n            <div class=\"beat loopmark\">↺ “Redo to the perfect output” — fires 3×</div>\n            <div class=\"beat\">Dashboard · what was wanted at turn 1</div>\n          </div>\n          <div class=\"cost\">Cost · 2 rebuild rounds (C1) — “perfect” has no observable test · N01</div>\n        </div>\n        <div class=\"pane\">\n          <span class=\"who\">The assistant’s side · no default</span>\n          <h3>“Please confirm one detail first”</h3>\n          <div class=\"cycle\">\n            <div class=\"beat\">Statement of Causal Harm drafted, 2 PDFs out</div>\n            <div class=\"beat\">4 more documents promised</div>\n            <div class=\"beat loopmark\">↺ “Confirm the starting month” — asked 3×</div>\n            <div class=\"beat dead\">Thread ends · 0 of 4 delivered</div>\n          </div>\n          <div class=\"cost\">Cost · 4 documents lost (C8), 5 confirmation round-trips (C7) · N26, N27</div>\n        </div>\n      </div>\n      <p class=\"fixline\"><b>Same defect, opposite directions.</b> One is fixed by a Done-when test. The other by propose-then-confirm — produce the draft, state the assumption inline, invite the correction. Neither needs more effort, only a rule. And the second is the one the responder can fix without me changing anything.</p>\n    </div>\n  </section>\n\n  <section id=\"patterns\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Pattern map · click any row to pull its evidence</div>\n      <h2>Seven patterns, ordered by observed cost</h2>\n    </div>\n    <div class=\"patterns\" id=\"pcards\"></div>\n  </section>\n\n  <section id=\"fixes\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Stall points → the one-line fix</div>\n      <h2>Where the approach breaks</h2>\n    </div>\n    <div class=\"tablewrap\">\n      <table>\n        <thead><tr><th style=\"width:30%\">Stall</th><th style=\"width:30%\">Cost in this corpus</th><th>Fix</th></tr></thead>\n        <tbody>\n          <tr class=\"act\"><td>Ask-then-wait<span class=\"now\">Act now</span></td><td>4 documents undelivered (C8), 5 round-trips (C7), 1 deliverable lost (C3)</td><td><b>Propose-then-confirm.</b> Never a question instead of a draft; never more than one question.</td></tr>\n          <tr class=\"act\"><td>No externalised “done”<span class=\"now\">Act now</span></td><td>2 rebuild rounds (C1)</td><td>A Done-when test on every task. Already in the standing instructions.</td></tr>\n          <tr class=\"act\"><td>Un-pre-empted render step<span class=\"now\">Act now</span></td><td>One round in each of 6 conversations</td><td>Ship the artefact in the first pass — dashboard, PDF, or both.</td></tr>\n          <tr><td>Session re-priming tax</td><td>3 of 3 ChatGPT threads reopen by re-declaring the mode</td><td>Persist the instruction set in a file. This repository is that fix.</td></tr>\n          <tr><td>Completeness-blind metrics</td><td>6.7 vs 5.7 on the same data and date</td><td>Print “inputs present: X/Y” beside any composite score.</td></tr>\n          <tr><td>Un-glossed shorthand</td><td>2–3 rounds (C1)</td><td>A six-line glossary in the standing instructions.</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section id=\"evidence\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Evidence · 34 atomic notes · zero orphan claims</div>\n      <h2>Every claim, with its source</h2>\n    </div>\n    <div class=\"filters\" id=\"filters\">\n      <div class=\"fgroup\"><span class=\"flabel\">Type</span>\n        <button class=\"f\" data-k=\"type\" data-v=\"all\" aria-pressed=\"true\">All</button>\n        <button class=\"f\" data-k=\"type\" data-v=\"Process\" aria-pressed=\"false\">Process</button>\n        <button class=\"f\" data-k=\"type\" data-v=\"Content\" aria-pressed=\"false\">Content</button>\n      </div>\n      <div class=\"fgroup\"><span class=\"flabel\">Platform</span>\n        <button class=\"f\" data-k=\"plat\" data-v=\"all\" aria-pressed=\"true\">All</button>\n        <button class=\"f\" data-k=\"plat\" data-v=\"Claude\" aria-pressed=\"false\">Claude</button>\n        <button class=\"f\" data-k=\"plat\" data-v=\"ChatGPT\" aria-pressed=\"false\">ChatGPT</button>\n      </div>\n      <div class=\"fgroup\"><span class=\"flabel\">Source</span>\n        <button class=\"f\" data-k=\"src\" data-v=\"all\" aria-pressed=\"true\">All</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C1\" aria-pressed=\"false\">C1</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C2\" aria-pressed=\"false\">C2</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C3\" aria-pressed=\"false\">C3</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C4\" aria-pressed=\"false\">C4</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C5\" aria-pressed=\"false\">C5</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C6\" aria-pressed=\"false\">C6</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C7\" aria-pressed=\"false\">C7</button>\n        <button class=\"f\" data-k=\"src\" data-v=\"C8\" aria-pressed=\"false\">C8</button>\n      </div>\n      <span class=\"fstate\" id=\"fstate\">34 of 34</span>\n    </div>\n    <div class=\"notes\" id=\"notes\"></div>\n  </section>\n\n  <section id=\"gaps\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Gap list · what is thin, missing, or unverified</div>\n      <h2>What would make this map trustworthy</h2>\n    </div>\n    <div class=\"tablewrap\">\n      <table>\n        <thead><tr><th style=\"width:7%\">ID</th><th style=\"width:29%\">Gap</th><th style=\"width:16%\">Severity</th><th>What closes it</th></tr></thead>\n        <tbody>\n          <tr><td class=\"id\">G1</td><td>8 of ~50 conversations</td><td class=\"sev s-high\"><span class=\"dot\"></span>High<span class=\"tag\">narrowed</span></td><td>Export the remaining ~42.</td></tr>\n          <tr><td class=\"id\">G10</td><td>My own messages absent from the three ChatGPT threads</td><td class=\"sev s-high\"><span class=\"dot\"></span>High<span class=\"tag\">new</span></td><td>Re-export with user turns — the exporter dropped them. Cheapest high-value fix.</td></tr>\n          <tr><td class=\"id\">G2</td><td>2021 – mid-2025 absent</td><td class=\"sev s-high\"><span class=\"dot\"></span>High<span class=\"tag\">narrowed</span></td><td>Add pre-2025 exports; sort by conversation date, not export date.</td></tr>\n          <tr><td class=\"id\">G3</td><td>Domain coverage still narrow</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium<span class=\"tag\">was high</span></td><td>Add workflow, finance, clinical-practice, technical conversations.</td></tr>\n          <tr><td class=\"id\">G11</td><td>Promised deliverables absent in 4 of 8</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium<span class=\"tag\">new</span></td><td>Re-export those four threads in full, or confirm the documents exist.</td></tr>\n          <tr><td class=\"id\">G5</td><td>Content notes unverified</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium</td><td>Verify health citations; treat legal content as pleading, not fact.</td></tr>\n          <tr><td class=\"id\">G6</td><td>Raw source data absent</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium</td><td>Attach wearable CSVs; index the legal exhibit bundle.</td></tr>\n          <tr><td class=\"id\">G7</td><td>Self-reported profile and claims unconfirmed</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium</td><td>Confirm against records before clinical or legal use.</td></tr>\n          <tr><td class=\"id\">G4</td><td>C3 deliverable truncated</td><td class=\"sev s-med\"><span class=\"dot\"></span>Medium</td><td>Re-export C3 including the research output.</td></tr>\n          <tr><td class=\"id\">G8</td><td>Exports show summaries, not full outputs</td><td class=\"sev s-low\"><span class=\"dot\"></span>Low</td><td>Export full message bodies, not collapsed thought-process.</td></tr>\n          <tr><td class=\"id\">G12</td><td>Authorship of the prompt-examples file unknown</td><td class=\"sev s-low\"><span class=\"dot\"></span>Low<span class=\"tag\">new</span></td><td>Confirm whether it is mine or installed with a skill.</td></tr>\n          <tr><td class=\"id\">G9</td><td>Separating my patterns from the AI’s</td><td class=\"sev s-low\"><span class=\"dot\"></span>Low<span class=\"tag\">mostly closed</span></td><td>Five of seven patterns replicate across two platforms. A non-LLM source would settle the rest.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"scopebox\">\n      <b>Do first: G10, then G1.</b> Re-exporting the three ChatGPT threads <em>with my messages</em> is cheap and upgrades three conversations from inference to direct evidence — it also makes the shorthand pattern testable outside C1 for the first time. Then volume, oldest first: the single most valuable new capability this round was seeing the same person five months apart.\n    </div>\n  </section>\n\n  <section id=\"phasep\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Phase P · prospective</div>\n      <h2>The three prompts you are most likely to need next</h2>\n    </div>\n    <p class=\"lede\" style=\"margin-bottom:20px\">Each is grounded in a named pattern — no orphan predictions. <strong>Method flag:</strong> this ran in-thread on instruction, not in fresh context, so it may over-fit to specifics I have just read. Treated as Medium confidence for that reason.<br><br><strong>Pre-empted rather than predicted:</strong> the highest-probability next ask in the corpus is “now make it a PDF.” Per its own fix, it ships in this pass instead of being forecast.</p>\n    <div id=\"preds\"></div>\n  </section>\n\n  <section id=\"handoff\">\n    <div class=\"shead\">\n      <div class=\"eyebrow\">Handoff card · Round 2 of 2 complete</div>\n      <h2>Where this stops</h2>\n    </div>\n    <div class=\"handoff\">\n      <div class=\"hgrid\">\n        <div class=\"hitem\"><span class=\"k\">Goal</span><span class=\"v\">Turn exported AI history into atomic notes + pattern map + gap list, every claim traceable, feeding a BigQuery/RAG second brain.</span></div>\n        <div class=\"hitem\"><span class=\"k\">Done-when</span><span class=\"v\"><strong>Partial pass.</strong> <em>Three artefacts plus Phase P, zero orphan claims, gaps named — on 8 conversations across 5 months, not ~50 across 5 years.</em></span></div>\n        <div class=\"hitem\"><span class=\"k\">What Round 2 bought</span><span class=\"v\"><em>Cross-checking. Five of seven patterns replicate on two platforms and two domains, so they are far more likely mine than one model’s habit.</em></span></div>\n        <div class=\"hitem\"><span class=\"k\">Open</span><span class=\"v\"><em>G10 and G1 are the blockers. G11 blocks confirming that initiative delivers and confirmation-seeking does not.</em></span></div>\n        <div class=\"hitem\"><span class=\"k\">Pipeline</span><span class=\"v\"><em>Notes map 1:1 to the guide’s <code>documents</code> rows — N-id, title, body, plus source, platform, confidence and gap as tags. No embeddings generated here. Watson X stays deferred.</em></span></div>\n        <div class=\"hitem\"><span class=\"k\">Do not</span><span class=\"v\"><em>Re-open this thread to improve it. Rounds are spent. Start fresh: fix the corpus, or re-run Phase P in clean context and compare.</em></span></div>\n      </div>\n    </div>\n    <div class=\"scopebox\">\n      <b>Verdict: PASSES</b> for “prove the pipeline and cross-check it on a second platform and domain.” Does <em>not</em> pass the literal ~50-conversation done-when. The method is validated; the corpus is the constraint.\n    </div>\n  </section>\n\n  <footer>\n    <span>Confidence in the map: Medium-High — five of seven patterns cross-checked on two platforms.</span>\n    <span>Generalisation beyond these two domains: Medium.</span>\n    <span>Behavioural, not clinical. Legal content is declared, not adjudicated.</span>\n  </footer>\n</div>\n\n<script>\n(function () {\n  \"use strict\";\n\n  var PATTERNS = [\n    { id:\"P6\", claim:\"Clarifying questions are the main stall\",\n      stall:\"Ask-then-wait costs rounds and sometimes kills the thread. He has explicitly asked for initiative instead — twice, a year apart, on two platforms.\",\n      notes:[\"N06\",\"N25\",\"N26\",\"N27\",\"N28\"], conf:\"High\", cross:\"2 platforms · 2 domains\", isnew:true },\n    { id:\"P1\", claim:\"Loops without a stop rule, in both directions\",\n      stall:\"He re-issues “make it perfect” with no exit test; the assistant re-asks one question with no default. Same defect, mirrored.\",\n      notes:[\"N01\",\"N07\",\"N27\"], conf:\"High\", cross:\"2 platforms\", isnew:false },\n    { id:\"P3\", claim:\"The predictable second step: render it as a deliverable\",\n      stall:\"A structured answer is only finished once it becomes an artefact — a dashboard for data, a court-ready PDF for law.\",\n      notes:[\"N03\",\"N24\"], conf:\"High\", cross:\"6 of 8 conversations\", isnew:false },\n    { id:\"P4\", claim:\"Heavy front-loaded scaffolding, versioned, domain-independent\",\n      stall:\"Schemas, formulas, guardrails, node-and-edge architecture maps, v1 → v2 → v3. Applied to biology and to litigation alike.\",\n      notes:[\"N04\",\"N05\",\"N12\",\"N22\",\"N23\"], conf:\"High\", cross:\"2 domains · promoted\", isnew:false },\n    { id:\"P7\", claim:\"Every map gets a score\",\n      stall:\"A structured map is immediately followed by a triage layer that collapses it into one priority verdict.\",\n      notes:[\"N32\",\"N12\",\"N31\"], conf:\"High\", cross:\"2 domains\", isnew:true },\n    { id:\"P8\", claim:\"The instruction set is rebuilt every session\",\n      stall:\"Three of three ChatGPT threads open by re-declaring the operating mode. The hand-maintained schema dates to October 2025.\",\n      notes:[\"N20\",\"N30\"], conf:\"High\", cross:\"ChatGPT threads\", isnew:true },\n    { id:\"P2\", claim:\"Shorthand the AI must decode over rounds\",\n      stall:\"“Audiovisuals”, “cognitive wish” carry stable intent; interpretation lags two to three rounds.\",\n      notes:[\"N02\",\"N08\"], conf:\"Medium\", cross:\"C1 only — untestable in C6–C8\", isnew:false },\n    { id:\"P5\", claim:\"Answer fragility on incomplete data\",\n      stall:\"Headline metric swings about a point on same-day data gaps. Same question, two numbers, no completeness flag.\",\n      notes:[\"N09\",\"N10\"], conf:\"Medium\", cross:\"health only\", isnew:false }\n  ];\n\n  var PREDICTIONS = [\n    { n:1, title:\"Scale the pipeline to the full corpus\", conf:\"High\",\n      why:\"G1 is the named blocker and you already know it. P4 shows you scale a proven scaffold rather than redesigning it, and N30 shows this project has been running since October 2025. The move after “it works on 8” is “run it on everything.”\",\n      prompt:\"Agentic Memory — Field Test #2. Run the Phase R pipeline over my full conversation export, not a sample.\\n\\nOutcome: every conversation becomes atomic notes in the same schema as agentic-memory/field-test-01/01-ATOMIC-NOTES.md, rolled into one pattern map and one gap list.\\n\\nDone-when: (a) every conversation is either processed or listed as unprocessable with a reason; (b) zero orphan claims — every claim names its source conversation; (c) each pattern states how many conversations, platforms, domains and months it spans; (d) any pattern found in only one domain is labelled as such.\\n\\nRounds: 2.\\n\\nBefore starting, inventory what is actually present and tell me what is missing. Do not fill gaps to look complete. Prioritise conversations dated before October 2025 — that is the thinnest part of the corpus. Output an artefact.\" },\n    { n:2, title:\"Score and triage the pattern map\", conf:\"High\",\n      why:\"P7 and N32 — every structured map you build gets a triage layer straight afterwards: Loop Score with four bands, severity 90 out of 100, Danger Radar, Now / Next 2 / Later. Four conversations, two domains, two platforms. In your corpus, a map without a score is an unfinished map. N31 sets the constraint: counts and bands, no invented decimals.\",\n      prompt:\"Take the Round 2 pattern map in agentic-memory/field-test-01/02-PATTERN-MAP.md and add a triage layer.\\n\\nOutcome: each pattern carries (a) how many conversations, platforms and domains it appears in — counts, not estimates; (b) the observed cost in rounds or undelivered deliverables; (c) a band — Act now / Monitor / Note only; (d) the single fix, in one line.\\n\\nDone-when: the patterns are ordered by observed cost rather than by how interesting they are, and every count traces to named conversations. No composite score, no decimals — bands and counts only.\\n\\nRounds: 1.\\n\\nThen tell me which one fix to make this week and what changes if I make it.\" },\n    { n:3, title:\"Make the notes queryable\", conf:\"Medium\",\n      why:\"N11 and N30 — the point of the second brain is retrieval, not note-taking. The BigQuery guide is attached, the note-to-documents field mapping is already written, and the notes were built atomic so they would load. Labelled Medium because nothing in the corpus shows you actually running an ingest — this is inference about intent, not an observed pattern.\",\n      prompt:\"Turn the field-test-01 atomic notes into a working retrieval layer using the pipeline in Personal_Data_Embedding_Living_AI_Guide.md.\\n\\nOutcome: the notes exist as newline-delimited JSONL matching the guide''s documents schema, ready to load, with source, confidence and gap carried as metadata tags.\\n\\nDone-when: (a) one JSONL row per note, validated against the guide''s field list; (b) I can ask \\\"where does my approach stall?\\\" and get back the specific notes with their source conversations; (c) any step needing my credentials or a manual console action is listed separately as a handoff, not silently skipped.\\n\\nRounds: 2.\\n\\nFlag every manual step and propose the automated route. Watson X stays deferred. No code in your explanation to me unless I say \\\"show code.\\\"\" }\n  ];\n\n  var NOTES = [\n    { id:\"N01\", type:\"Process\", plat:[\"Claude\"], src:[\"C1\"], conf:\"High\",\n      title:\"I re-issue a near-identical “perfect output / red-team” prompt until satisfied, with no stated stop condition\",\n      body:\"The same meta-instruction fires at least three times in one thread. Each firing makes the AI rebuild from scratch. Because “perfect” and “cognitive wish” are never given an observable test, the loop has no exit — it can recurse indefinitely. This is the exact failure the Done-when and anti-resonation rules are built to stop.\",\n      source:\"C1 pp. 16 & 21 — the sentence appears verbatim twice, after an initial “redo”.\",\n      why:\"Identical prompt text visible on two pages.\", gap:\"\" },\n    { id:\"N02\", type:\"Process\", plat:[\"Claude\"], src:[\"C1\"], conf:\"High\",\n      title:\"“Audiovisuals” is my shorthand for “make it interactive, not prose” — the AI needed 2–3 rounds to decode it\",\n      body:\"The word escalates across turns as the AI keeps returning text. It eventually decodes to “build a dashboard”, which ends the escalation. The intent was stable from turn 1; only the interpretation lagged. A one-word gloss in standing instructions would collapse this to a single round.\",\n      source:\"C1 p.2 → p.16 → p.21, escalating each time.\",\n      why:\"High for the recurrence; Medium for the intended meaning, inferred from the dashboard being accepted.\",\n      gap:\"No explicit line confirming “a dashboard is what I meant”.\" },\n    { id:\"N03\", type:\"Process\", plat:[\"Claude\"], src:[\"C2\",\"C4\",\"C5\"], conf:\"High\",\n      title:\"“Help me visualize this data” is my reflexive second move — verbatim across three separate conversations\",\n      body:\"The sequence is stable: request analysis → receive report → immediately ask for a visualization. Predictable enough to pre-empt: delivering report and dashboard in the first pass removes an entire round.\",\n      source:\"C2 p.10, C4 p.21, C5 p.26 — identical string in all three.\",\n      why:\"Identical string, three independent exports.\", gap:\"\" },\n    { id:\"N04\", type:\"Process\", plat:[\"Claude\"], src:[\"C2\",\"C4\"], conf:\"High\",\n      title:\"I front-load heavy scaffolding — exact schemas, formulas, anti-fabrication rules — to constrain the AI before it runs\",\n      body:\"Prompts specify CSV column names, parse code, a 5-node scoring formula, tiered alert thresholds, a contraindicated-drug list, and rules such as “NEVER fabricate” and “cite file + column”. I engineer the guardrails myself rather than trusting defaults. Buys precision; high effort and brittle.\",\n      source:\"C2 pp.2–4, C4 pp.2–15.\", why:\"The scaffolding is the bulk of both conversations.\", gap:\"\" },\n    { id:\"N05\", type:\"Process\", plat:[\"Claude\"], src:[\"C4\",\"C2\"], conf:\"High\",\n      title:\"I version my master-prompts — the nonadherence prompt is explicitly “v2.0 (Red-Team Validated)”\",\n      body:\"C4 restates C2''s patient context, data schemas and Loop Score formula in a cleaner, numbered, more defensive form and labels itself v2.0. Prompts are treated as maintained software artefacts, not one-off messages.\",\n      source:\"C4 p.2 title block vs C2 p.2.\", why:\"Version label and near-duplicate structure both visible.\", gap:\"\" },\n    { id:\"N06\", type:\"Process\", plat:[\"Claude\"], src:[\"C3\"], conf:\"High\",\n      title:\"When asked clarifying questions, I delegate the decision back rather than specifying\",\n      body:\"Faced with three clarifying questions — budget, use pattern, coverage — I removed two constraints and handed the third back. Implication: clarifying questions are often friction. Design consequence — prefer propose-then-confirm over ask-then-wait.\",\n      source:\"C3 p.6 — “co0st no matter”, “as often as I can”, “I want you to recommend the correct answer”.\",\n      why:\"Answers quoted verbatim.\", gap:\"Single conversation in Round 1; corroborated in Round 2 by N25.\" },\n    { id:\"N07\", type:\"Process\", plat:[\"Claude\"], src:[\"C1\"], conf:\"Medium\",\n      title:\"My corrections target form and depth, not factual errors — I rarely dispute a specific claim\",\n      body:\"Across the visible correction turns, none says “that number is wrong”. Every correction pushes for better rendering or a deeper pass. Strength: fast to a usable artefact. Latent risk: the correction budget never lands on fact-checking, so errors in the content notes would survive review.\",\n      source:\"C1 pp.16, 21.\", why:\"Inferred from absence of factual disputes in a small visible set.\",\n      gap:\"Only C1 contains explicit correction turns.\" },\n    { id:\"N08\", type:\"Process\", plat:[\"Claude\"], src:[\"C3\"], conf:\"High\",\n      title:\"I frame the AI as a cognitive layer for a verbal thinker, not merely a tool\",\n      body:\"The stated self-model is consistent: language in, finished cognition out; the AI does the translation to the technical layer. Same premise as the standing operating instructions — the operating system is itself a compensatory response to how I think.\",\n      source:\"C3 p.2 — “an additional layer or transformer… aiding a verbal thinker to maximize AI use”.\",\n      why:\"Quoted, and echoed by the session''s own preamble.\", gap:\"\" },\n    { id:\"N09\", type:\"Process\", plat:[\"Claude\"], src:[\"C2\",\"C4\"], conf:\"High\",\n      title:\"Same data, same date, same formula produced two different Loop Scores — 6.7 vs 5.7\",\n      body:\"Both target 2026-03-15, the same person, the same 5-node formula. The scores diverge mainly on the node that depends on same-day symptom logging, which was partially absent. A headline metric that swings about a point on data completeness needs an explicit completeness flag beside it.\",\n      source:\"C2 p.8 (6.7, “today''s entries are incomplete”) vs C4 p.20 (5.7, WARNING).\",\n      why:\"High for the two numbers; Medium for pinning the delta to one node.\",\n      gap:\"Raw CSVs not in session — cannot recompute.\" },\n    { id:\"N10\", type:\"Content\", plat:[\"Claude\"], src:[\"C2\",\"C4\"], conf:\"High\",\n      title:\"Across both clinical reports the AI independently ranks propranolol non-adherence as the #1 lever\",\n      body:\"Both reports surface the same dominant real-world lever: adherence, reported at 38% / 20% / eight consecutive missed doses. The most stable finding the data produces. Recorded as a recurring signal in the corpus — not as a medical recommendation.\",\n      source:\"C2 p.9, C4 p.20.\", why:\"High that both reports ranked it first.\",\n      gap:\"Adherence figures AI-reported from CSVs not present; unverified.\" },\n    { id:\"N11\", type:\"Process\", plat:[\"Claude\"], src:[\"C1\"], conf:\"High\",\n      title:\"I am building the meta-system that would automate the n-of-1 analysis I keep running by hand\",\n      body:\"CNN for feature extraction from wearable inputs, RNN for longitudinal memory, RL for experiment selection — each layer mapped to a real research system. The through-line: turn personal data into a self-improving retrieval and decision system. Same ambition as this field test.\",\n      source:\"C1 pp.3–4, 9–15.\", why:\"Architecture is spelled out.\",\n      gap:\"Aspirational design; no evidence any of it is deployed.\" },\n    { id:\"N12\", type:\"Content\", plat:[\"Claude\"], src:[\"C4\",\"C2\"], conf:\"High\",\n      title:\"Substrate: the 5-node Loop Score is my own composite metric, defined by explicit formula\",\n      body:\"LS = (Autonomic + Sleep + Inflammatory/PEM + Pharmacologic + Deconditioning) / 15 × 10, each node 0–3. Bands: 0–3 stable, 3–5 monitoring, 5–7 warning, 7–10 critical. An invented instrument for compressing multi-stream data into one number.\",\n      source:\"C4 pp.5–6, C2 p.3.\", why:\"Formula quoted.\", gap:\"Instrument validity out of scope here.\" },\n    { id:\"N13\", type:\"Content\", plat:[\"Claude\"], src:[\"C2\",\"C4\"], conf:\"High\",\n      title:\"Substrate: self-reported clinical profile stated in-prompt — declared, not confirmed\",\n      body:\"Age 32; ICD implanted Feb 2023 with follow-up overdue; Long COVID, POTS, Brugada, DM2, active VZV, ME-CFS overlap; baseline over 166 days HRV ~20 ms, RHR ~84 bpm, recovery 36%, sleep ~5 h. User-supplied context, not a verified record.\",\n      source:\"C2 p.2, C4 p.2.\", why:\"High that it is stated.\", gap:\"Unverified medical history — treat as declared.\" },\n    { id:\"N14\", type:\"Content\", plat:[\"Claude\"], src:[\"C1\"], conf:\"High\",\n      title:\"Substrate: behavioural and dietary identity surfaced from my own files\",\n      body:\"Halal 100%, intermittent fasting ~35% of days, magnesium and L-theanine, ~0% alcohol, ~12% caffeine. Corpus: WHOOP 277 days, Oura 62 days, 1,399 journal entries across 47 unique questions — named as the reinforcement-learning training signal.\",\n      source:\"C1 pp.23–25.\", why:\"High that the AI reported them; Medium that figures are exact.\",\n      gap:\"Underlying files not in session.\" },\n    { id:\"N15\", type:\"Content\", plat:[\"Claude\"], src:[\"C1\"], conf:\"Medium\",\n      title:\"Substrate: meal decode headline — peanut butter blunts the spike about 30%\",\n      body:\"Bread + Nutella + peanut butter ≈ 525 kcal at roughly 49/41/10 fat/carb/protein; Nutella ~57% sugar by weight; peanut butter blunts the glucose spike about 30%. Optimal protocol offered: morning, peanut-butter-first, whole-wheat.\",\n      source:\"C1 pp.4–6.\", why:\"AI synthesis with PMIDs, not independently checked here.\",\n      gap:\"Citations unverified in this session.\" },\n    { id:\"N16\", type:\"Content\", plat:[\"Claude\"], src:[\"C5\"], conf:\"Medium\",\n      title:\"Substrate: POTS pharmacotherapy ranking\",\n      body:\"The synthesis ranks ivabradine and low-dose propranolol strongest for heart-rate control, and guanfacine as the best dual POTS + ADHD agent. Fludrocortisone weak; midodrine, salt and compression complementary.\",\n      source:\"C5 pp.5–7, 16.\", why:\"Tagged peer-reviewed, unverified here.\", gap:\"Citations unverified.\" },\n    { id:\"N17\", type:\"Content\", plat:[\"Claude\"], src:[\"C5\"], conf:\"Medium\",\n      title:\"Substrate: GLP-1 risk thesis — flagged high-risk for this profile\",\n      body:\"GLP-1 agonists raise heart rate through a sinus-node mechanism ivabradine cannot block, and suppress HRV by about 6 ms — meaningful from an already-low baseline. Net position: defer pending the named trials.\",\n      source:\"C5 pp.11–12, 22–24.\", why:\"Mechanistic claims tagged peer-reviewed, unverified here.\",\n      gap:\"Citations unverified.\" },\n    { id:\"N18\", type:\"Content\", plat:[\"Claude\"], src:[\"C5\"], conf:\"Medium\",\n      title:\"Substrate: MCAS-as-driver thesis plus an empiric antihistamine trial\",\n      body:\"Mast Cell Activation Syndrome — an over-reactive mast-cell condition — is framed as a likely under-diagnosed driver of POTS via a mast-cell to sympathetic feedback loop. An empiric H1/H2 antihistamine trial is presented as low-risk, high-reward.\",\n      source:\"C5 pp.18–20.\", why:\"Tagged peer-reviewed, unverified here.\",\n      gap:\"Citations unverified; a diagnostic hypothesis, not a diagnosis.\" },\n    { id:\"N19\", type:\"Process\", plat:[\"Claude\"], src:[\"C3\"], conf:\"High\",\n      title:\"Gap-note: C3''s actual deliverable is absent from the export\",\n      body:\"The compression-wrap conversation is captured only up to the moment research launches — no product list, no recommendation, no pressures or sizing. Any downstream claim about what I was told must come from C5''s corroborating evidence, not from C3.\",\n      source:\"C3 p.6 — thread ends at the research launch.\", why:\"The truncation point is visible.\",\n      gap:\"The deliverable itself is the gap.\" },\n\n    { id:\"N20\", type:\"Process\", plat:[\"ChatGPT\"], src:[\"C6\",\"C7\",\"C8\"], conf:\"High\",\n      title:\"All three ChatGPT threads open with me re-priming a standing instruction set\",\n      body:\"The operating instructions do not persist, so every session begins with a re-priming tax before any work happens. Three sessions, three re-primes, identical mode with the same five processing rules. This is the same problem the standing instructions file and this repository exist to solve.\",\n      source:\"C6, C7, C8 — the first assistant turn in each is “Living Notebook mode resumed”, listing parse → analyse → structure → tag → triage.\",\n      why:\"The acknowledgment is explicit and identical in all three.\",\n      gap:\"My actual priming text is not captured — only the readback of it.\" },\n    { id:\"N21\", type:\"Process\", plat:[\"ChatGPT\"], src:[\"C6\",\"C7\",\"C8\"], conf:\"High\",\n      title:\"The ChatGPT exports contain only assistant turns — my own messages are absent\",\n      body:\"What I asked has to be reconstructed from what the AI answered. Some is recoverable with high confidence because the AI quotes or paraphrases the instruction, but every behavioural claim drawn from these three is one inference-step removed from the Claude notes, where my prompts are visible verbatim.\",\n      source:\"C6, C7, C8 — every block is headed “Response:”. No user turns anywhere.\",\n      why:\"Structural and plainly visible.\", gap:\"This is the gap. Re-export with user messages included.\" },\n    { id:\"N22\", type:\"Process\", plat:[\"ChatGPT\",\"Claude\"], src:[\"C6\",\"C1\"], conf:\"High\",\n      title:\"I apply the same architecture metaphor to a second, unrelated domain: a “Convolutional Narrative Network” map of my litigation\",\n      body:\"Health data and legal causation get the same treatment: entities as nodes, relationships as edges, a layered flow from input to output, and a feedback loop described as back-propagation. The metaphor engine is domain-independent — so the scaffolding pattern is not a health-analysis habit, it is how I structure any complex problem.\",\n      source:\"C6 — CNN Map v2 then v3: nodes N1–N18, edges, legal axes A1–A6, “Network Flow”. Versus C1''s biological CNN→RNN→RL.\",\n      why:\"Both maps are explicit and labelled.\", gap:\"\" },\n    { id:\"N23\", type:\"Process\", plat:[\"ChatGPT\",\"Claude\"], src:[\"C6\",\"C4\"], conf:\"High\",\n      title:\"I version artefacts in the legal domain exactly as I do in the health domain\",\n      body:\"Same behaviour, different subject: produce, label a version, then merge and strengthen into the next. C6''s v3 is explicitly described as merging the earlier map with new material. Confirms the versioning pattern across platform and domain.\",\n      source:\"C6 — CNN Map v2 → v3, Affidavit A / Affidavit B. Versus C4 — master-prompt v2.0.\",\n      why:\"Version labels visible in both.\", gap:\"\" },\n    { id:\"N24\", type:\"Process\", plat:[\"ChatGPT\",\"Claude\"], src:[\"C2\",\"C4\",\"C5\",\"C6\",\"C7\",\"C8\"], conf:\"High\",\n      title:\"The reflexive second move is “render it as a deliverable” — a dashboard for data, a court-ready PDF for law\",\n      body:\"The constant is not charts. It is that a structured answer is only finished once it becomes an artefact; the medium is domain-dependent. Practical consequence: the artefact should ship in the first pass, whatever the domain.\",\n      source:\"Health — “Help me visualize this data” in C2, C4, C5. Legal — every thread pivots from a markdown node to generated PDFs: C6 four, C7 five, C8 two.\",\n      why:\"High for the pattern across 6 of 8 conversations; Medium for reading the two forms as one drive.\",\n      gap:\"My request wording in C6–C8 is not visible.\" },\n    { id:\"N25\", type:\"Process\", plat:[\"ChatGPT\"], src:[\"C6\"], conf:\"High\",\n      title:\"I explicitly instructed the assistant to stop asking for confirmations and take initiative\",\n      body:\"Confirms the delegation pattern on a second platform, in a second domain, a year apart. Clarifying questions are friction, not help. The design rule that follows is propose-then-confirm: produce the draft, state the assumption, let me correct it.\",\n      source:\"C6 — “Understood. I''ll take full initiative on drafting and optimizing all filings without pausing for minor confirmations.” Live corroboration: this session''s own instruction, “Re-run and automatically proceed to next step.”\",\n      why:\"The readback is verbatim-style and behaviour changed immediately afterwards.\",\n      gap:\"My exact wording not captured.\" },\n    { id:\"N26\", type:\"Process\", plat:[\"ChatGPT\"], src:[\"C7\"], conf:\"High\",\n      title:\"Five consecutive assistant turns in C7 asked for confirmations before producing a single document\",\n      body:\"Five round-trips of formatting questions before the first deliverable — and every one was answerable by proposing a default and noting it. This is the concrete cost of ask-then-wait, and the highest-leverage stall in the corpus because it is entirely avoidable by the responder.\",\n      source:\"C7 — sequential requests for institution identifiers, then tone, then address vs placeholders, then combined vs separate files, then typeface and spacing.\",\n      why:\"The five turns are consecutive and visible.\",\n      gap:\"My replies are absent, so my tolerance for each question is unknown.\" },\n    { id:\"N27\", type:\"Process\", plat:[\"ChatGPT\"], src:[\"C8\"], conf:\"High\",\n      title:\"C8 ends with the same question asked three times in a row; four promised documents were never produced\",\n      body:\"The mirror image of the perfect-output recursion. There I loop because no exit test was defined; here the assistant loops because it will not proceed without one datum. The loop stalls whenever neither side holds a stop rule. A default-and-flag — “assuming April 2024, correct me” — would have delivered four documents.\",\n      source:\"C8 — the final three assistant turns each request “the approximate starting month of financial loss”. Legal Memorandum, Affidavit of Fact, Financial Loss Statement and Health Impact Declaration all promised and absent.\",\n      why:\"Three identical consecutive requests are visible.\",\n      gap:\"Cannot tell whether I replied and the export dropped it, or the thread genuinely died.\" },\n    { id:\"N28\", type:\"Process\", plat:[\"ChatGPT\",\"Claude\"], src:[\"C6\",\"C7\",\"C8\",\"C3\"], conf:\"Medium\",\n      title:\"In this corpus, initiative produced deliverables and confirmation-seeking produced none\",\n      body:\"The two threads that ended with nothing delivered both ended on a confirmation question. The thread where I told the assistant to act produced the most artefacts. Not absolute — C7 shows confirmations can eventually yield — but the direction is consistent across four conversations and two platforms.\",\n      source:\"C6 after “take full initiative”: 4 PDFs + 2 full maps, and one turn states “Next, I will automatically proceed”. C7: 5 confirmation turns, PDFs eventually, promised markdown set never. C8: deadlock, nothing. C3: clarifying questions, deliverable absent.\",\n      why:\"n=4, and my turns are not visible, so cause and effect cannot be fully separated.\",\n      gap:\"Needs the remaining conversations to test.\" },\n    { id:\"N29\", type:\"Process\", plat:[\"ChatGPT\",\"Claude\"], src:[\"C1\",\"C2\",\"C3\",\"C4\",\"C5\",\"C6\",\"C7\",\"C8\"], conf:\"Medium\",\n      title:\"I run the same operating pattern on two different AI platforms\",\n      body:\"The strongest available test of whether these are my patterns or one model''s habits — and they replicate: front-loaded scaffolding, versioned artefacts, render-to-deliverable second step, initiative over questions, node-and-edge metaphors. This largely retires the original “can''t separate me from the AI” gap.\",\n      source:\"C1–C5 on Claude, C6–C8 on ChatGPT.\",\n      why:\"The patterns clearly appear on both; the inference “therefore mine, not the AI''s” is strong but not conclusive — both are instruction-following assistants with similar training.\",\n      gap:\"A structurally different source would settle it.\" },\n    { id:\"N30\", type:\"Process\", plat:[\"ChatGPT\",\"Claude\"], src:[\"C6\",\"C7\",\"C8\",\"C1\"], conf:\"High\",\n      title:\"The externalised-memory project predates the “second brain” design by about five months\",\n      body:\"The first genuinely longitudinal observation in the corpus. I was hand-running a structured second brain in October 2025; the 2026 architecture is an attempt to automate what I was already doing manually. This field test is the third iteration of the same project.\",\n      source:\"C6/C7/C8 — RLN date-coded IDs, YAML front-matter, backlinks, an explicit folder tree, SCQH + MECE triage, Now / Next 2 / Later, “Danger Radar”. Versus C1 (Feb–Mar 2026) proposing CNN→RNN→RL.\",\n      why:\"Date codes and export stamps are explicit on both ends.\",\n      gap:\"The Oct 2025 → Feb 2026 middle is missing; whether the system was sustained is unknown.\" },\n    { id:\"N31\", type:\"Process\", plat:[\"ChatGPT\",\"Claude\"], src:[\"C2\",\"C4\",\"C8\"], conf:\"High\",\n      title:\"My own instruments use decimal scores; my instruction to the AI forbids them\",\n      body:\"Not a contradiction — a boundary. Numbers computed from data are wanted; numbers the AI invents to sound precise are not. The rule is anti-false-precision, not anti-quantification. Practical read: bands for judgment, exact figures only where they trace to a source.\",\n      source:\"C2 Loop Score 6.7, C4 5.7, C8 severity 90/100 from Impact 10 × Urgency 10 × Risk 9 − Effort 7. Versus the standing rule “Confidence = High / Medium / Low. Never a decimal.”\",\n      why:\"High that both exist; Medium for this interpretation of why.\",\n      gap:\"The rationale is inferred — I have not stated it.\" },\n    { id:\"N32\", type:\"Process\", plat:[\"ChatGPT\",\"Claude\"], src:[\"C2\",\"C4\",\"C6\",\"C7\",\"C8\"], conf:\"High\",\n      title:\"I score and triage every map I build\",\n      body:\"Across both domains, a structured map is immediately followed by a triage layer that converts it into a single priority verdict. Four conversations, two domains, two platforms. Strong predictor of what I will ask for next after any map.\",\n      source:\"C8 severity 90 → “Critical Priority”. C2/C4 Loop Score with four bands. C6 “Danger Radar” risk × severity × urgency. C7 Now / Next 2 / Later.\",\n      why:\"Explicit scoring instruments in four conversations.\", gap:\"\" },\n    { id:\"N33\", type:\"Content\", plat:[\"ChatGPT\"], src:[\"C6\",\"C7\",\"C8\"], conf:\"High\",\n      title:\"Content: the legal claim structure I am assembling — declared, not adjudicated\",\n      body:\"Six axes: employment retaliation, privacy, education due process, civil rights, defamation, immigration hardship. Damages ledger subtotal $693,000 across eight line items. Causation chain: academic-record falsification → licensure block → employment loss → housing, insurance and health harm. Filing deadlines tracked.\",\n      source:\"C6, C7, C8 — affidavits, RLN nodes and the damages ledger.\",\n      why:\"High that these are the assertions in my documents.\",\n      gap:\"Unverified and unadjudicated. No court records in session. Recorded as corpus content, not findings of fact; no legal opinion attached.\" },\n    { id:\"N34\", type:\"Process\", plat:[], src:[], conf:\"High\",\n      title:\"The two reference files are not conversations and cannot support behavioural claims\",\n      body:\"Both are distilled reference material with no dialogue and no ask-to-outcome sequence. What they show, weakly: I maintain structured reference files for both tooling and one-off practical problems, consistent with the October 2025 evidence.\",\n      source:\"R1 examples.md — prompt-optimisation examples across 10 platforms, matching a skill in my workspace, authorship unknown. R2 cybertruck_domain_knowledge.md — 48V jump-start facts and NYC sourcing.\",\n      why:\"High that they are not conversations; Low for any behavioural inference from them.\",\n      gap:\"Authorship of the examples file unknown.\" }\n  ];\n\n  var state = { type:\"all\", src:\"all\", plat:\"all\", pattern:null };\n\n  function esc(s) {\n    return String(s).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\");\n  }\n\n  /* pattern cards */\n  var pwrap = document.getElementById(\"pcards\");\n  PATTERNS.forEach(function (p) {\n    var b = document.createElement(\"button\");\n    b.type = \"button\";\n    b.className = \"pcard\";\n    b.setAttribute(\"aria-pressed\", \"false\");\n    b.dataset.p = p.id;\n    b.innerHTML =\n      ''<div class=\"prow\"><span class=\"id\">'' + p.id + ''</span>'' +\n      ''<span class=\"claim\">'' + esc(p.claim) + ''</span>'' +\n      ''<span class=\"chips\">'' + (p.isnew ? ''<span class=\"chip new\">new</span>'' : '''') +\n      ''<span class=\"chip x\">'' + esc(p.cross) + ''</span>'' +\n      ''<span class=\"chip\">'' + p.notes.join(\" · \") + ''</span>'' +\n      ''<span class=\"chip\">'' + p.conf + ''</span></span></div>'' +\n      ''<div class=\"stall\">'' + esc(p.stall) + ''</div>'';\n    b.addEventListener(\"click\", function () {\n      state.pattern = (state.pattern === p.id) ? null : p.id;\n      syncPatterns();\n      render();\n      if (state.pattern) {\n        document.getElementById(\"evidence\").scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n      }\n    });\n    pwrap.appendChild(b);\n  });\n\n  function syncPatterns() {\n    Array.prototype.forEach.call(pwrap.children, function (el) {\n      el.setAttribute(\"aria-pressed\", el.dataset.p === state.pattern ? \"true\" : \"false\");\n    });\n  }\n\n  /* filters */\n  var fbtns = document.querySelectorAll(\"#filters .f\");\n  Array.prototype.forEach.call(fbtns, function (btn) {\n    btn.addEventListener(\"click\", function () {\n      state[btn.dataset.k] = btn.dataset.v;\n      state.pattern = null;\n      syncPatterns();\n      Array.prototype.forEach.call(fbtns, function (o) {\n        if (o.dataset.k === btn.dataset.k) {\n          o.setAttribute(\"aria-pressed\", o === btn ? \"true\" : \"false\");\n        }\n      });\n      render();\n    });\n  });\n\n  var nwrap = document.getElementById(\"notes\");\n  var fstate = document.getElementById(\"fstate\");\n\n  function visible(n) {\n    if (state.pattern) {\n      var p = PATTERNS.filter(function (x) { return x.id === state.pattern; })[0];\n      return p.notes.indexOf(n.id) !== -1;\n    }\n    if (state.type !== \"all\" && n.type !== state.type) { return false; }\n    if (state.src !== \"all\" && n.src.indexOf(state.src) === -1) { return false; }\n    if (state.plat !== \"all\" && n.plat.indexOf(state.plat) === -1) { return false; }\n    return true;\n  }\n\n  function render() {\n    var shown = NOTES.filter(visible);\n    nwrap.innerHTML = shown.map(function (n) {\n      var confCls = n.conf === \"High\" ? \"high\" : \"med\";\n      var platTag = n.plat.length ? ''<span class=\"typetag\">'' + n.plat.join(\"+\") + ''</span>'' : '''';\n      return ''<details class=\"note'' + (state.pattern ? \" lit\" : \"\") + ''\"'' + (state.pattern ? \" open\" : \"\") + ''>'' +\n        ''<summary><span class=\"id\">'' + n.id + ''</span>'' +\n        ''<span class=\"ntitle\">'' + esc(n.title) + ''</span>'' +\n        ''<span class=\"nmeta\">'' + platTag + ''<span class=\"typetag\">'' + n.type + ''</span>'' +\n        ''<span class=\"conf '' + confCls + ''\">'' + n.conf + ''</span></span></summary>'' +\n        ''<div class=\"nbody\"><p>'' + esc(n.body) + ''</p>'' +\n        ''<div class=\"nsrc\">Source · '' + esc(n.source) + ''<br>Confidence · '' + n.conf + '' — '' + esc(n.why) + ''</div>'' +\n        ''<div class=\"ngap'' + (n.gap ? \"\" : \" none\") + ''\">Gap · '' + esc(n.gap || \"none\") + ''</div></div></details>'';\n    }).join(\"\");\n    fstate.textContent = state.pattern\n      ? shown.length + \" supporting \" + state.pattern + \" — click \" + state.pattern + \" again to clear\"\n      : shown.length + \" of \" + NOTES.length;\n  }\n  render();\n\n  /* predictions */\n  var pr = document.getElementById(\"preds\");\n  pr.innerHTML = PREDICTIONS.map(function (p, i) {\n    return ''<div class=\"pred\"><div class=\"prow\"><span class=\"id\">P'' + p.n + ''</span>'' +\n      ''<h3>'' + esc(p.title) + ''</h3>'' +\n      ''<span class=\"chips\"><span class=\"chip\">'' + p.conf + '' confidence</span></span></div>'' +\n      ''<p class=\"why\">'' + esc(p.why) + ''</p>'' +\n      ''<div class=\"promptbox\"><button class=\"copy\" type=\"button\" data-i=\"'' + i + ''\">Copy</button>'' +\n      ''<pre id=\"pt'' + i + ''\">'' + esc(p.prompt) + ''</pre></div></div>'';\n  }).join(\"\");\n\n  Array.prototype.forEach.call(document.querySelectorAll(\".copy\"), function (btn) {\n    btn.addEventListener(\"click\", function () {\n      var text = document.getElementById(\"pt\" + btn.dataset.i).textContent;\n      var done = function () {\n        btn.textContent = \"Copied\";\n        setTimeout(function () { btn.textContent = \"Copy\"; }, 1600);\n      };\n      if (navigator.clipboard && navigator.clipboard.writeText) {\n        navigator.clipboard.writeText(text).then(done, function () { btn.textContent = \"Select manually\"; });\n      } else {\n        btn.textContent = \"Select manually\";\n      }\n    });\n  });\n})();\n</script>\n", "file_path": "/home/user/claude-/agentic-memory/field-test-01/field-test-01.html"}');
