INSERT INTO blocks (block_id, turn_uuid, turn_no, seq, role, kind, chars, tool_name, tool_use_id, is_error, redacted, signature_sha256, signature_len, privacy_zone, zone_reason, zone_match, text) VALUES (261, 'b522fd26-b057-4821-8acf-a81f27a9aec9', 197, 2, 'assistant', 'tool_use', 711, 'Bash', 'toolu_01SKPAR3B6tPwnJMve3mdevd', 0, 0, NULL, NULL, 'Private work', 'session-internal', '', '{"command": "python3 -c \"\nimport json\np=''/root/.claude/projects/-home-user-claude-/7f4839a0-2759-5274-a271-16ea4d44156c.jsonl''\nfor line in open(p,encoding=''utf-8''):\n    if not line.strip(): continue\n    d=json.loads(line)\n    m=d.get(''message'')\n    if isinstance(m,dict) and isinstance(m.get(''content''),list):\n        for b in m[''content'']:\n            if isinstance(b,dict) and b.get(''type'')==''thinking'':\n                print(''keys:'', sorted(b.keys()))\n                for k,v in b.items():\n                    print(''  '',k,''='',type(v).__name__, (len(v) if isinstance(v,str) else ''''), repr(v)[:120])\n                raise SystemExit\n\"", "description": "Inspect a thinking block''s field names"}');
