INSERT INTO blocks (block_id, turn_uuid, turn_no, seq, role, kind, chars, tool_name, tool_use_id, is_error, redacted, signature_sha256, signature_len, privacy_zone, zone_reason, zone_match, text) VALUES (314, '4978a19c-e5a4-46bd-b6cc-4131762c36bc', 241, 1, 'assistant', 'tool_use', 1894, 'Edit', 'toolu_01Cue6xs82R3TFz5mJLombec', 0, 0, NULL, NULL, 'Private work', 'session-internal', '', '{"replace_all": false, "file_path": "/home/user/claude-/agentic-memory/session-export/build_export.py", "old_string": "    turns, blocks, tools, usage = [], [], [], []\n    tool_by_id = {}\n    bid = 0\n    turn_no = 0\n\n    for rec in recs:\n        msg = rec.get(\"message\")\n        if not isinstance(msg, dict):\n            continue\n        role = msg.get(\"role\")\n        if role not in (\"user\", \"assistant\"):\n            continue\n        turn_no += 1\n        uuid = rec.get(\"uuid\")", "new_string": "    turns, blocks, tools, usage = [], [], [], []\n    tool_by_id = {}\n    bid = 0\n    turn_no = 0\n    # The CLI writes one content block per record, so consecutive records that\n    # share a message id are one logical model response. Grouping them is what\n    # makes a \"turn\" mean a turn - and stops usage being counted once per\n    # block instead of once per response.\n    turn_index = {}\n    seq_in_turn = Counter()\n\n    for rec in recs:\n        msg = rec.get(\"message\")\n        if not isinstance(msg, dict):\n            continue\n        role = msg.get(\"role\")\n        if role not in (\"user\", \"assistant\"):\n            continue\n        gkey = (msg.get(\"id\") or rec.get(\"requestId\") or rec.get(\"uuid\")\n                if role == \"assistant\" else rec.get(\"uuid\"))\n        if gkey in turn_index:\n            uuid = turn_index[gkey]\n            existing = next(t for t in turns if t[\"uuid\"] == uuid)\n            turn_no = existing[\"turn_no\"]\n            for seq, b in enumerate(blocks_of(msg)):\n                bid, blocks, tools = _emit_block(\n                    b, bid, blocks, tools, uuid, turn_no,\n                    seq_in_turn[uuid], role, tool_by_id)\n                seq_in_turn[uuid] += 1\n            continue\n        turn_no = len(turns) + 1\n        uuid = rec.get(\"uuid\")\n        turn_index[gkey] = uuid"}');
